//! PyO3 Python bindings for FrankenPandas.
//!
//! Exposes DataFrame, Series, and core operations to Python.
//!
//! ```python
//! import frankenpandas as fp
//!
//! # Create a Series
//! s = fp.Series([1, 2, 3, 4, 5], name="values")
//! print(s.sum())  # 15
//!
//! # Create a DataFrame
//! df = fp.DataFrame({"a": [1, 2, 3], "b": [4.0, 5.0, 6.0]})
//! print(df.head(2))
//! ```

#![forbid(unsafe_code)]
#![allow(clippy::collapsible_if, clippy::needless_range_loop)]

use std::{
    collections::{BTreeMap, BTreeSet, HashMap, HashSet},
    sync::{LazyLock, Mutex},
};

use fp_columnar::{ArithmeticOp, Column, ComparisonOp};
use fp_expr::DataFrameExprExt;
use fp_frame::{
    DataFrame, DropNaHow, FrameError, PlotKind, Series, concat_dataframes, concat_series,
};
use fp_index::{
    AlignMode, CategoricalIndex, DatetimeIndex, DuplicateKeep, Index, IndexLabel, MultiIndex,
    OrderedF64, PeriodIndex, RangeIndex, TimedeltaIndex, format_datetime_ns,
};
use fp_types::{DType, NullKind, Period, PeriodFreq, Scalar, Timedelta, Timestamp};
use mimalloc::MiMalloc;
use pyo3::{
    IntoPyObjectExt,
    prelude::*,
    types::{PyDict, PyFrozenSet, PyList, PySet, PyTuple},
};

#[global_allocator]
static GLOBAL: MiMalloc = MiMalloc;

/// Parse frequency string like "D", "2D", "h", "30s", "min", "ms", "us", "ns" into nanoseconds.
fn parse_freq_to_nanos(freq: &str) -> PyResult<i64> {
    let s = freq.trim();
    if s.is_empty() {
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "empty freq",
        ));
    }
    let split_pos = s.find(|c: char| !c.is_ascii_digit()).unwrap_or(s.len());
    let (count_str, unit_str) = s.split_at(split_pos);
    let count: i64 = if count_str.is_empty() {
        1
    } else {
        count_str.parse().map_err(|_| {
            PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "invalid freq count: {count_str}"
            ))
        })?
    };
    let unit = unit_str.trim();
    let base_nanos = match unit {
        "D" | "d" => 86_400_000_000_000_i64,
        "h" | "H" => 3_600_000_000_000_i64,
        "min" | "T" | "m" => 60_000_000_000_i64,
        "s" | "S" => 1_000_000_000_i64,
        "ms" | "L" => 1_000_000_i64,
        "us" | "U" => 1_000_i64,
        "ns" | "N" | "" => 1_i64,
        other => {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "unsupported frequency: {other}"
            )));
        }
    };
    count
        .checked_mul(base_nanos)
        .ok_or_else(|| PyErr::new::<pyo3::exceptions::PyValueError, _>("frequency overflow"))
}

/// Map a pandas dtype name to a FrankenPandas `DType` with pandas' meanings:
/// "Int64"/"Float64"/"boolean" are the nullable dtypes, "category" is
/// categorical (fp-types' `FromStr`); "i64"/"f64" are binding aliases.
fn parse_dtype(name: &str) -> PyResult<fp_types::DType> {
    use fp_types::DType;
    match name {
        "i64" => Ok(DType::Int64),
        "f64" => Ok(DType::Float64),
        other => other.parse::<DType>().map_err(|_| {
            PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                "data type '{other}' not understood"
            ))
        }),
    }
}

/// pandas' name for a dtype, as `Series.dtype` / `DataFrame.dtypes` print it.
fn pandas_dtype_name(dtype: &fp_types::DType) -> String {
    use fp_types::DType;
    match dtype {
        DType::Int64 => "int64".to_owned(),
        DType::Int64Nullable => "Int64".to_owned(),
        DType::Float64 => "float64".to_owned(),
        DType::Float64Nullable => "Float64".to_owned(),
        DType::Bool => "bool".to_owned(),
        DType::BoolNullable => "boolean".to_owned(),
        DType::Utf8 | DType::Null => "object".to_owned(),
        DType::Categorical => "category".to_owned(),
        DType::Datetime64 { tz: None } => "datetime64[ns]".to_owned(),
        DType::Datetime64 { tz: Some(tz) } => format!("datetime64[ns, {tz}]"),
        DType::Timedelta64 => "timedelta64[ns]".to_owned(),
        other => format!("{other:?}").to_ascii_lowercase(),
    }
}

/// Convert a Python dict `{old: new}` into FrankenPandas `(Scalar, Scalar)` pairs.
fn py_dict_to_scalar_pairs(
    py: Python<'_>,
    mapping: &Bound<'_, PyDict>,
) -> PyResult<Vec<(Scalar, Scalar)>> {
    let mut pairs = Vec::with_capacity(mapping.len());
    for (k, v) in mapping.iter() {
        pairs.push((py_to_scalar(py, &k)?, py_to_scalar(py, &v)?));
    }
    Ok(pairs)
}

fn days_from_ymd(year: i64, month: i64, day: i64) -> i64 {
    let y = if month <= 2 { year - 1 } else { year };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let doy = (153 * (if month > 2 { month - 3 } else { month + 9 }) + 2) / 5 + day - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

/// Missing value sentinel `NAType` (pandas `pd.NA`).
#[pyclass(name = "NAType", from_py_object)]
#[derive(Clone, Debug)]
pub struct PyNAType;

#[pymethods]
impl PyNAType {
    #[new]
    fn new() -> Self {
        PyNAType
    }

    fn __repr__(&self) -> &'static str {
        "<NA>"
    }

    fn __str__(&self) -> &'static str {
        "<NA>"
    }

    fn __bool__(&self) -> PyResult<bool> {
        Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
            "boolean value of NA is ambiguous",
        ))
    }

    fn __hash__(&self) -> isize {
        133742
    }

    fn __richcmp__<'py>(
        &self,
        py: Python<'py>,
        _other: &Bound<'py, PyAny>,
        _op: pyo3::class::basic::CompareOp,
    ) -> PyResult<Py<PyAny>> {
        PyNAType.into_py_any(py)
    }
}

