    fn mean(&self) -> Option<String> {
        if self.inner.is_empty() {
            return None;
        }
        let sum: i64 = self.inner.values().iter().map(|p| p.ordinal).sum();
        let avg = sum / self.inner.len() as i64;
        let p = Period::new(avg, self.inner.values()[0].freq);
        Some(p.to_string())
    }

