    fn asof(&self, py: Python<'_>, label: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        let lbl = py_to_index_label(label)?;
        let val = self.inner.asof_value(&lbl).map_err(frame_error_to_py)?;
        scalar_to_py(py, &val)
    }

    #[pyo3(signature = (lag=None))]
    fn autocorr(&self, lag: Option<usize>) -> PyResult<f64> {
        let l = lag.unwrap_or(1);
        self.inner.autocorr(l).map_err(frame_error_to_py)
    }

    #[pyo3(signature = (ascending=true))]
    fn argsort(&self, ascending: bool) -> PyResult<PySeries> {
        let res = self.inner.argsort(ascending).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: res })
    }

    #[pyo3(signature = (func, convert_dtype=true, args=None, **kwargs))]
    fn apply(
        &self,
        py: Python<'_>,
        func: &Bound<'_, PyAny>,
        convert_dtype: bool,
        args: Option<&Bound<'_, PyTuple>>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PySeries> {
        unsupported_params("Series.apply", &[("convert_dtype", convert_dtype)])?;
        let vals = self.inner.column().values();
        let labels = self.inner.index().labels();
        let mut out = Vec::with_capacity(vals.len());
        for v in vals {
            let py_val = scalar_to_py(py, v)?;
            let res = if let Some(extra_args) = args {
                let mut full_args = Vec::with_capacity(1 + extra_args.len());
                full_args.push(py_val);
                for a in extra_args.iter() {
                    full_args.push(a.into_any().unbind());
                }
                let t = PyTuple::new(py, &full_args)?;
                func.call(t, kwargs)?
            } else if kwargs.is_some() {
                let t = PyTuple::new(py, &[py_val])?;
                func.call(t, kwargs)?
            } else {
                func.call1((py_val,))?
            };
            out.push(py_to_scalar(py, &res)?);
        }
        let s = Series::from_values(self.inner.name(), labels.to_vec(), out)
            .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    #[pyo3(signature = (arg, na_action=None))]
    fn map(
        &self,
        py: Python<'_>,
        arg: &Bound<'_, PyAny>,
        na_action: Option<&str>,
    ) -> PyResult<PySeries> {
        let ignore_na = na_action == Some("ignore");
        let vals = self.inner.column().values();
        let labels = self.inner.index().labels();
        if arg.is_callable() {
            let mut out = Vec::with_capacity(vals.len());
            for v in vals {
                if ignore_na && (v.is_null() || matches!(v, Scalar::Float64(f) if f.is_nan())) {
                    out.push(v.clone());
                    continue;
                }
                let py_val = scalar_to_py(py, v)?;
                let res = arg.call1((py_val,))?;
                out.push(py_to_scalar(py, &res)?);
            }
            let s = Series::from_values(self.inner.name(), labels.to_vec(), out)
                .map_err(frame_error_to_py)?;
            Ok(PySeries { inner: s })
        } else if let Ok(dict) = arg.cast::<PyDict>() {
            let mut out = Vec::with_capacity(vals.len());
            for v in vals {
                if ignore_na && (v.is_null() || matches!(v, Scalar::Float64(f) if f.is_nan())) {
                    out.push(v.clone());
                    continue;
                }
                let py_val = scalar_to_py(py, v)?;
                if let Some(mapped) = dict.get_item(&py_val)? {
                    out.push(py_to_scalar(py, &mapped)?);
                } else {
                    out.push(Scalar::Float64(f64::NAN));
                }
            }
            let s = Series::from_values(self.inner.name(), labels.to_vec(), out)
                .map_err(frame_error_to_py)?;
            Ok(PySeries { inner: s })
        } else if let Ok(other_ser) = arg.extract::<PyRef<PySeries>>() {
            let mut out = Vec::with_capacity(vals.len());
            for v in vals {
                if ignore_na && (v.is_null() || matches!(v, Scalar::Float64(f) if f.is_nan())) {
                    out.push(v.clone());
                    continue;
                }
                let lbl = match v {
                    Scalar::Utf8(s) => IndexLabel::Utf8(s.clone()),
                    Scalar::Int64(i) => IndexLabel::Int64(*i),
                    Scalar::Float64(f) => IndexLabel::Float64(OrderedF64(*f)),
                    Scalar::Bool(b) => IndexLabel::Bool(*b),
                    _ => IndexLabel::Utf8(v.to_string()),
                };
                let col_val = if let Some(idx_pos) = other_ser.inner.index().get_loc(&lbl) {
                    other_ser
                        .inner
                        .column()
                        .values()
                        .get(idx_pos)
                        .cloned()
                        .unwrap_or(Scalar::Float64(f64::NAN))
                } else {
                    Scalar::Float64(f64::NAN)
                };
                out.push(col_val);
            }
            let s = Series::from_values(self.inner.name(), labels.to_vec(), out)
                .map_err(frame_error_to_py)?;
            Ok(PySeries { inner: s })
        } else {
            Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "map expects a callable, dict, or Series",
            ))
        }
    }

    #[pyo3(signature = (percentiles=None))]
    fn describe(&self, percentiles: Option<Vec<f64>>) -> PyResult<PySeries> {
        let s = match percentiles {
            Some(p) => self
                .inner
                .describe_with_percentiles(&p)
                .map_err(frame_error_to_py)?,
            None => self.inner.describe().map_err(frame_error_to_py)?,
        };
        Ok(PySeries { inner: s })
    }

    fn dot(&self, other: &PySeries) -> PyResult<f64> {
        self.inner.dot(&other.inner).map_err(frame_error_to_py)
    }

    #[pyo3(signature = (cond, other=None, inplace=false, axis=None, level=None))]
    fn r#where(
        &mut self,
        py: Python<'_>,
        cond: &Bound<'_, PyAny>,
        other: Option<&Bound<'_, PyAny>>,
        inplace: Option<bool>,
        axis: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PySeries>> {
        unsupported_params("Series.where", &[("level", level.is_none())])?;
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        let cond_series = normalize_series_cond(py, &self.inner, cond)?;
        let other_val = normalize_series_other(py, &self.inner, other)?;
        let res_inner = execute_series_where(&self.inner, &cond_series, &other_val)?;
        if inplace.unwrap_or(false) {
            self.inner = res_inner;
            Ok(None)
        } else {
            Ok(Some(PySeries { inner: res_inner }))
        }
    }

    #[pyo3(signature = (cond, other=None, inplace=false, axis=None, level=None))]
    fn mask(
        &mut self,
        py: Python<'_>,
        cond: &Bound<'_, PyAny>,
        other: Option<&Bound<'_, PyAny>>,
        inplace: Option<bool>,
        axis: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PySeries>> {
        unsupported_params("Series.mask", &[("level", level.is_none())])?;
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        let cond_series = normalize_series_cond(py, &self.inner, cond)?;
        let not_cond_series = cond_series.not().map_err(frame_error_to_py)?;
        let other_val = normalize_series_other(py, &self.inner, other)?;
        let res_inner = execute_series_where(&self.inner, &not_cond_series, &other_val)?;
        if inplace.unwrap_or(false) {
            self.inner = res_inner;
            Ok(None)
        } else {
            Ok(Some(PySeries { inner: res_inner }))
        }
    }

    #[pyo3(signature = (func, *args, **kwargs))]
    fn pipe<'py>(
        &self,
        py: Python<'py>,
        func: &Bound<'py, PyAny>,
        args: &Bound<'py, pyo3::types::PyTuple>,
        kwargs: Option<&Bound<'py, PyDict>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        if let Ok(tup) = func.cast::<pyo3::types::PyTuple>()
            && tup.len() == 2
        {
            let f = tup.get_item(0)?;
            let kw_name = tup.get_item(1)?.extract::<String>()?;
            let kw = kwargs.cloned().unwrap_or_else(|| PyDict::new(py));
            kw.set_item(kw_name, self.clone())?;
            return f.call(args, Some(&kw));
        }
        let mut full_args = Vec::with_capacity(args.len() + 1);
        full_args.push(Py::new(py, self.clone())?.into_any());
        for item in args.iter() {
            full_args.push(item.clone().unbind());
        }
        let tuple_args = pyo3::types::PyTuple::new(py, full_args)?;
        func.call(tuple_args, kwargs)
    }

    #[pyo3(signature = (items=None, like=None, regex=None, axis=None))]
    fn filter(
        &self,
        py: Python<'_>,
        items: Option<Vec<String>>,
        like: Option<&str>,
        regex: Option<&str>,
        axis: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PySeries> {
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        if let Some(items_list) = items {
            let mut matched_labels = Vec::new();
            let mut matched_values = Vec::new();
            let labels = self.inner.index().labels();
            let values = self.inner.column().values();
            for item in items_list {
                for (lbl, val) in labels.iter().zip(values.iter()) {
                    if lbl.to_string() == item {
                        matched_labels.push(lbl.clone());
                        matched_values.push(val.clone());
                        break;
                    }
                }
            }
            let s = Series::from_values(self.inner.name(), matched_labels, matched_values)
                .map_err(frame_error_to_py)?;
            Ok(PySeries { inner: s })
        } else if let Some(sub) = like {
            let mut matched_labels = Vec::new();
            let mut matched_values = Vec::new();
            let labels = self.inner.index().labels();
            let values = self.inner.column().values();
            for (lbl, val) in labels.iter().zip(values.iter()) {
                if lbl.to_string().contains(sub) {
                    matched_labels.push(lbl.clone());
                    matched_values.push(val.clone());
                }
            }
            let s = Series::from_values(self.inner.name(), matched_labels, matched_values)
                .map_err(frame_error_to_py)?;
            Ok(PySeries { inner: s })
        } else if let Some(pat) = regex {
            let re_mod = py.import("re")?;
            let mut matched_labels = Vec::new();
            let mut matched_values = Vec::new();
            let labels = self.inner.index().labels();
            let values = self.inner.column().values();
            for (lbl, val) in labels.iter().zip(values.iter()) {
                let lbl_str = lbl.to_string();
                let is_match = re_mod
                    .call_method1("search", (pat, &lbl_str))?
                    .is_truthy()?;
                if is_match {
                    matched_labels.push(lbl.clone());
                    matched_values.push(val.clone());
                }
            }
            let s = Series::from_values(self.inner.name(), matched_labels, matched_values)
                .map_err(frame_error_to_py)?;
            Ok(PySeries { inner: s })
        } else {
            Ok(self.clone())
        }
    }

    #[pyo3(signature = (key, default=None))]
    fn get<'py>(
        &self,
        py: Python<'py>,
        key: &Bound<'py, PyAny>,
        default: Option<&Bound<'py, PyAny>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        if let Ok(seq) = key.extract::<Vec<Bound<'py, PyAny>>>() {
            let mut labels = Vec::with_capacity(seq.len());
            for item in &seq {
                if let Ok(label) = py_to_index_label(item) {
                    if self.inner.index().position(&label).is_none() {
                        return Ok(default.cloned().unwrap_or_else(|| py.None().into_bound(py)));
                    }
                    labels.push(label);
                } else {
                    return Ok(default.cloned().unwrap_or_else(|| py.None().into_bound(py)));
                }
            }
            if let Ok(s) = self.inner.loc(&labels) {
                let py_s = Py::new(py, PySeries { inner: s })?;
                return Ok(py_s.into_bound(py).into_any());
            }
            return Ok(default.cloned().unwrap_or_else(|| py.None().into_bound(py)));
        }
        let label = match py_to_index_label(key) {
            Ok(l) => l,
            Err(_) => return Ok(default.cloned().unwrap_or_else(|| py.None().into_bound(py))),
        };
        let positions: Vec<usize> = self
            .inner
            .index()
            .labels()
            .iter()
            .enumerate()
            .filter(|(_, l)| *l == &label)
            .map(|(i, _)| i)
            .collect();
        if positions.len() > 1 {
            if let Ok(sub) = self.inner.loc(&[label]) {
                let py_s = Py::new(py, PySeries { inner: sub })?;
                return Ok(py_s.into_bound(py).into_any());
            }
        } else if let Some(pos) = positions.first() {
            let sc = &self.inner.column().values()[*pos];
            let py_val = scalar_to_py(py, sc)?;
            return Ok(py_val.into_bound(py));
        }
        Ok(default.cloned().unwrap_or_else(|| py.None().into_bound(py)))
    }

    fn first(&self, offset: &str) -> PyResult<PySeries> {
        let s = self.inner.first_offset(offset).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    fn last(&self, offset: &str) -> PyResult<PySeries> {
        let s = self.inner.last_offset(offset).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    #[getter]
    fn is_unique(&self) -> bool {
        self.inner.is_unique()
    }

    #[getter]
    fn is_monotonic_increasing(&self) -> bool {
        self.inner.is_monotonic_increasing()
    }

    #[getter]
    fn is_monotonic_decreasing(&self) -> bool {
        self.inner.is_monotonic_decreasing()
    }

    /// pandas' `Series.reindex`. `method` fills absent labels from the
    /// neighbouring source label, `fill_value` fills whatever is still missing
    /// at an absent label (fvsao.5: both used to be dropped through `**kwargs`).
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (index=None, *, axis=None, method=None, copy=None, level=None, fill_value=None, limit=None, tolerance=None))]
    fn reindex(
        &self,
        py: Python<'_>,
        index: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        method: Option<&str>,
        copy: Option<bool>,
        level: Option<&Bound<'_, PyAny>>,
        fill_value: Option<&Bound<'_, PyAny>>,
        limit: Option<usize>,
        tolerance: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PySeries> {
        // copy= only lets pandas share buffers; a new Series satisfies it.
        let _ = copy;
        unsupported_params(
            "Series.reindex",
            &[
                ("level", level.is_none()),
                ("limit", limit.is_none()),
                ("tolerance", tolerance.is_none()),
            ],
        )?;
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        let Some(idx_obj) = index else {
            return Ok(self.clone());
        };
        let labels = if let Ok(py_idx) = idx_obj.extract::<PyRef<'_, PyIndex>>() {
            py_idx.inner.labels().to_vec()
        } else if let Ok(list) = idx_obj.cast::<PyList>() {
            let mut lbls = Vec::with_capacity(list.len());
            for item in list.iter() {
                lbls.push(py_to_index_label(&item)?);
            }
            lbls
        } else {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "reindex expects Index or list of labels",
            ));
        };
        let reindexed = match method {
            Some(m) => self.inner.reindex_with_method(labels.clone(), m),
            None => self.inner.reindex(labels.clone()),
        }
        .map_err(frame_error_to_py)?;
        let Some(fill) = fill_value.filter(|fv| !fv.is_none()) else {
            return Ok(PySeries { inner: reindexed });
        };
        let fill = py_to_scalar(py, fill)?;
        let source_positions = self.inner.index().get_indexer(&Index::new(labels.clone()));
        let values = reindexed
            .values()
            .iter()
            .zip(&source_positions)
            .map(|(value, source)| {
                if source.is_none() && value.is_missing() {
                    fill.clone()
                } else {
                    value.clone()
                }
            })
            .collect();
        let filled =
            Series::from_values(reindexed.name(), labels, values).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: filled })
    }

    fn ravel(&self, py: Python<'_>) -> PyResult<Py<PyList>> {
        let vals = self.inner.ravel();
        let list = PyList::empty(py);
        for v in vals {
            list.append(scalar_to_py(py, &v)?)?;
        }
        Ok(list.into())
    }

    fn factorize(&self) -> PyResult<(PySeries, PySeries)> {
        let (codes, uniques) = self.inner.factorize().map_err(frame_error_to_py)?;
        Ok((PySeries { inner: codes }, PySeries { inner: uniques }))
    }

    fn case_when(&self, caselist: &Bound<'_, PyList>) -> PyResult<PySeries> {
        let mut cases = Vec::with_capacity(caselist.len());
        for item in caselist.iter() {
            let pair = item.cast::<pyo3::types::PyTuple>()?;
            if pair.len() != 2 {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "case_when requires pairs of (condition, value)",
                ));
            }
            let cond = pair.get_item(0)?.extract::<PyRef<'_, PySeries>>()?;
            let val = pair.get_item(1)?.extract::<PyRef<'_, PySeries>>()?;
            cases.push((cond.inner.clone(), val.inner.clone()));
        }
        let s = self.inner.case_when(&cases).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    #[pyo3(signature = (other, level=None, fill_value=None, axis=None))]
    fn divmod(
        &self,
        py: Python<'_>,
        other: &Bound<'_, PyAny>,
        level: Option<&Bound<'_, PyAny>>,
        fill_value: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<(PySeries, PySeries)> {
        let q = self.floordiv(py, other, level, fill_value, axis)?;
        let r = self.r#mod(py, other, level, fill_value, axis)?;
        Ok((q, r))
    }

    #[pyo3(signature = (other, level=None, fill_value=None, axis=None))]
    fn rdivmod(
        &self,
        py: Python<'_>,
        other: &Bound<'_, PyAny>,
        level: Option<&Bound<'_, PyAny>>,
        fill_value: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<(PySeries, PySeries)> {
        let q = self.rfloordiv(py, other, level, fill_value, axis)?;
        let r = self.rmod(py, other, level, fill_value, axis)?;
        Ok((q, r))
    }

    #[pyo3(signature = (copy=None))]
    fn infer_objects(&self, copy: Option<bool>) -> PyResult<PySeries> {
        // copy= only lets pandas share buffers; a new Series satisfies it.
        let _ = copy;
        let s = self.inner.infer_objects().map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    /// pandas' `Series.interpolate`: linear honours `limit`,
    /// `limit_direction` and `limit_area`; nearest/zero/pad/index/values/time
    /// honour `limit` in the forward direction (fvsao.5: `method` and every
    /// option used to be dropped, so any call gave linear interpolation).
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (method="linear", *, axis=None, limit=None, inplace=false, limit_direction=None, limit_area=None, downcast=None, **kwargs))]
    fn interpolate(
        &self,
        method: &str,
        axis: Option<&Bound<'_, PyAny>>,
        limit: Option<usize>,
        inplace: bool,
        limit_direction: Option<&str>,
        limit_area: Option<&str>,
        downcast: Option<&Bound<'_, PyAny>>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PySeries> {
        unsupported_params("Series.interpolate", &[("downcast", downcast.is_none())])?;
        engine_kwargs("Series.interpolate", "scipy", kwargs)?;
        if inplace {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "inplace=True is not supported",
            ));
        }
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        if !Series::interpolate_supports(method, limit_direction, limit_area) {
            return Err(not_implemented(&format!(
                "Series.interpolate(method='{method}') with limit_direction or limit_area"
            )));
        }
        let s = self
            .inner
            .interpolate_with(method, limit, limit_direction, limit_area)
            .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    /// Drops level 0, the only level frankenpandas' single-level index has.
    #[pyo3(signature = (level=0))]
    fn droplevel(&self, level: usize) -> PyResult<PySeries> {
        unsupported_params("Series.droplevel", &[("level", level == 0)])?;
        let s = self.inner.droplevel().map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    fn unstack(&self) -> PyResult<PyDataFrame> {
        let df = self.inner.unstack().map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    #[pyo3(signature = (indices, axis=None, **kwargs))]
    fn take(
        &self,
        indices: Vec<i64>,
        axis: Option<&Bound<'_, PyAny>>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PySeries> {
        numpy_compat_kwargs("take", kwargs)?;
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        let s = self.inner.take(&indices).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    /// pandas' `Series.explode(ignore_index=False)` expands list-like values
    /// and leaves every scalar, strings included, as it is. A frankenpandas
    /// value is always a scalar, so the Series stays as it is. This used to
    /// split strings on a `sep` keyword pandas does not have (fvsao.5).
    #[pyo3(signature = (ignore_index=false))]
    fn explode(&self, ignore_index: bool) -> PyResult<PySeries> {
        if !ignore_index {
            return Ok(self.clone());
        }
        match self
            .inner
            .reset_index_with_name(true, None)
            .map_err(frame_error_to_py)?
        {
            fp_frame::SeriesResetIndexResult::Series(res) => Ok(PySeries { inner: res }),
            fp_frame::SeriesResetIndexResult::DataFrame(_) => unreachable!(),
        }
    }

