    /// Shift index by desired number of periods.
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (periods=1, freq=None, axis=None, fill_value=None, suffix=None))]
    fn shift(
        &self,
        periods: i64,
        freq: Option<&str>,
        axis: Option<&Bound<'_, PyAny>>,
        fill_value: Option<&Bound<'_, PyAny>>,
        suffix: Option<&str>,
    ) -> PyResult<PyDataFrame> {
        unsupported_params(
            "DataFrame.shift",
            &[("freq", freq.is_none()), ("suffix", suffix.is_none())],
        )?;
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        let fill_sc = match fill_value {
            Some(fv) => Some(py_to_scalar(fv.py(), fv)?),
            None => None,
        };
        let res = match ax {
            0 => {
                if let Some(sc) = fill_sc {
                    self.inner
                        .shift_with_fill_value(periods, sc)
                        .map_err(frame_error_to_py)?
                } else {
                    self.inner.shift(periods).map_err(frame_error_to_py)?
                }
            }
            1 => {
                if let Some(sc) = fill_sc {
                    self.inner
                        .shift_axis1_with_fill_value(periods, sc)
                        .map_err(frame_error_to_py)?
                } else {
                    self.inner.shift_axis1(periods).map_err(frame_error_to_py)?
                }
            }
            other => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "No axis named {other} for object type DataFrame"
                )));
            }
        };
        Ok(PyDataFrame { inner: res })
    }

    /// Assign new columns to a DataFrame, returning a new object (pandas `DataFrame.assign`).
    #[pyo3(signature = (**kwargs))]
    fn assign(&self, py: Python<'_>, kwargs: Option<&Bound<'_, PyDict>>) -> PyResult<PyDataFrame> {
        let mut df = self.inner.clone();
        if let Some(kwargs) = kwargs {
            for (key, val) in kwargs.iter() {
                let name = key.extract::<String>()?;
                let col = if val.is_callable() {
                    let py_df = Py::new(py, PyDataFrame { inner: df.clone() })?;
                    let res = val.call1((py_df,))?;
                    py_value_to_column(py, &res, df.len())?
                } else {
                    py_value_to_column(py, &val, df.len())?
                };
                df = df
                    .with_column(name, col)
                    .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
            }
        }
        Ok(PyDataFrame { inner: df })
    }

    /// Query the columns of a DataFrame with a boolean expression; pandas'
    /// `inplace=True` replaces the frame and returns None
    /// (br-frankenpandas-n57tz).
    #[pyo3(signature = (expr, inplace=false))]
    fn query(&mut self, expr: &str, inplace: bool) -> PyResult<Option<PyDataFrame>> {
        let res = self
            .inner
            .query(expr)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        if inplace {
            self.inner = res;
            return Ok(None);
        }
        Ok(Some(PyDataFrame { inner: res }))
    }

    /// Evaluate a string describing operations on DataFrame columns. With
    /// pandas' `inplace=True` an assignment (`c = a + b`) adds the column to
    /// this frame and returns None; without one it is pandas' ValueError
    /// (br-frankenpandas-n57tz).
    #[pyo3(signature = (expr, inplace=false))]
    fn eval(&mut self, py: Python<'_>, expr: &str, inplace: bool) -> PyResult<Py<PyAny>> {
        if let Some((target, rhs)) = expr.split_once('=') {
            let target = target.trim();
            if !target.is_empty()
                && !target.ends_with('!')
                && !target.ends_with('<')
                && !target.ends_with('>')
                && !target.ends_with('=')
                && !rhs.starts_with('=')
                && target.chars().all(|c| c.is_alphanumeric() || c == '_')
                && !target.starts_with(|c: char| c.is_ascii_digit())
            {
                let evaluated = self
                    .inner
                    .eval(rhs.trim())
                    .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
                let new_df = self
                    .inner
                    .with_column(target, evaluated.column().clone())
                    .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
                if inplace {
                    self.inner = new_df;
                    return Ok(py.None());
                }
                return Ok(Py::new(py, PyDataFrame { inner: new_df })?.into_any());
            }
        }
        if inplace {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "Cannot operate inplace if there is no assignment",
            ));
        }
        let evaluated = self
            .inner
            .eval(expr)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        Ok(Py::new(py, PySeries { inner: evaluated })?.into_any())
    }

    #[pyo3(signature = (window, min_periods=None, center=false))]
