    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (q=None, axis=None, numeric_only=false, interpolation="linear", method="single"))]
    fn quantile(
        &self,
        py: Python<'_>,
        q: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        numeric_only: bool,
        interpolation: &str,
        method: Option<&str>,
    ) -> PyResult<Py<PyAny>> {
        unsupported_params(
            "DataFrame.quantile",
            &[("method", matches!(method, None | Some("single")))],
        )?;
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        let target_df = if numeric_only {
            self.inner
                .select_dtypes(&[DType::Int64, DType::Float64, DType::Bool], &[])
                .map_err(frame_error_to_py)?
        } else {
            self.inner.clone()
        };

        let mut q_scalar: Option<f64> = None;
        let mut q_vec: Option<Vec<f64>> = None;

        if let Some(q_obj) = q {
            if let Ok(f) = q_obj.extract::<f64>() {
                q_scalar = Some(f);
            } else if let Ok(it) = q_obj.try_iter() {
                let mut vec = Vec::new();
                for item in it {
                    let item = item?;
                    vec.push(item.extract::<f64>()?);
                }
                q_vec = Some(vec);
            } else {
                return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                    "q must be a float or sequence of floats",
                ));
            }
        } else {
            q_scalar = Some(0.5);
        }

        if let Some(q_val) = q_scalar {
            let res = match ax {
                0 => target_df.quantile(q_val).map_err(frame_error_to_py)?,
                1 => target_df.quantile_axis1(q_val).map_err(frame_error_to_py)?,
                other => {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                        "No axis named {other} for object type DataFrame"
                    )));
                }
            };
            return Ok(Py::new(py, PySeries { inner: res })?.into_any());
        }

        if let Some(qs) = q_vec {
            let df_to_use = match ax {
                0 => target_df,
                1 => target_df.transpose().map_err(frame_error_to_py)?,
                other => {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                        "No axis named {other} for object type DataFrame"
                    )));
                }
            };

            let mut series_list = Vec::new();
            for col_name in df_to_use.column_names() {
                if let Some(col) = df_to_use.column(col_name) {
                    if matches!(col.dtype(), DType::Int64 | DType::Float64 | DType::Bool) {
                        let s =
                            Series::new(col_name.clone(), df_to_use.index().clone(), col.clone())
                                .map_err(frame_error_to_py)?;
                        let q_s = s
                            .quantile_list(&qs, interpolation)
                            .map_err(frame_error_to_py)?;
                        series_list.push(q_s);
                    }
                }
            }
            let res_df = if series_list.is_empty() {
                let index_labels: Vec<IndexLabel> = qs
                    .iter()
                    .map(|&q| IndexLabel::Float64(fp_index::OrderedF64(q)))
                    .collect();
                DataFrame::new_with_column_order(
                    Index::new(index_labels),
                    std::collections::BTreeMap::<String, Column>::new(),
                    Vec::<String>::new(),
                )
                .map_err(frame_error_to_py)?
            } else {
                DataFrame::from_series(series_list).map_err(frame_error_to_py)?
            };
            return Ok(Py::new(py, PyDataFrame { inner: res_df })?.into_any());
        }

        Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "Failed to evaluate quantile",
        ))
    }

    #[pyo3(signature = (axis=None, method=None, numeric_only=false, na_option=None, ascending=None, pct=false))]
    fn rank(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        method: Option<&str>,
        numeric_only: bool,
        na_option: Option<&str>,
        ascending: Option<bool>,
        pct: bool,
    ) -> PyResult<PyDataFrame> {
        let mut m = method.unwrap_or("average");
        let mut ax = 0;
        if let Some(a) = axis {
            if let Ok(s) = a.extract::<&str>() {
                if matches!(s, "average" | "min" | "max" | "first" | "dense") && method.is_none() {
                    m = s;
                } else {
                    ax = parse_axis_param_for_type(Some(a), "DataFrame")?.unwrap_or(0);
                }
            } else {
                ax = parse_axis_param_for_type(Some(a), "DataFrame")?.unwrap_or(0);
            }
        }
        let asc = ascending.unwrap_or(true);
        let na = na_option.unwrap_or("keep");

        let target_df = if numeric_only {
            self.inner
                .select_dtypes(&[DType::Int64, DType::Float64, DType::Bool], &[])
                .map_err(frame_error_to_py)?
        } else {
            self.inner.clone()
        };

        let res = if ax == 0 {
            target_df
                .rank_with_pct(m, asc, na, pct)
                .map_err(frame_error_to_py)?
        } else {
            target_df
                .rank_axis1_with_pct(m, asc, na, pct)
                .map_err(frame_error_to_py)?
        };
        Ok(PyDataFrame { inner: res })
    }

    #[pyo3(signature = (axis=None, skipna=true, ddof=1, numeric_only=false))]
    fn sem(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
        ddof: Option<usize>,
        numeric_only: bool,
    ) -> PyResult<PySeries> {
        let ax = parse_axis_param(axis)?;
        let ddof_val = ddof.unwrap_or(1);
        wrap_series(self.sem_internal(ax, skipna, ddof_val, numeric_only))
    }

    #[pyo3(signature = (axis=None, skipna=true, numeric_only=false))]
    fn skew(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
        numeric_only: bool,
    ) -> PyResult<PySeries> {
        let ax = parse_axis_param(axis)?;
        let skewed = self.skew_internal(ax, numeric_only);
        wrap_series(skewed.and_then(|s| self.missing_is_nan(s, ax, numeric_only, skipna)))
    }

    #[pyo3(signature = (axis=None, skipna=true, numeric_only=false))]
    fn kurt(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
        numeric_only: bool,
    ) -> PyResult<PySeries> {
        let ax = parse_axis_param(axis)?;
        let kurtosis = self.kurt_internal(ax, numeric_only);
        wrap_series(kurtosis.and_then(|s| self.missing_is_nan(s, ax, numeric_only, skipna)))
    }

    #[pyo3(signature = (axis=None, skipna=true, numeric_only=false))]
    fn kurtosis(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
        numeric_only: bool,
    ) -> PyResult<PySeries> {
        self.kurt(axis, skipna, numeric_only)
    }

    #[pyo3(signature = (before=None, after=None, axis=None, copy=None))]
    fn truncate(
        &self,
        before: Option<&Bound<'_, PyAny>>,
        after: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        copy: Option<bool>,
    ) -> PyResult<PyDataFrame> {
        let _ = copy;
        let axis_idx = parse_axis_param(axis)?;

        if axis_idx == 0 {
            let is_sorted = self.inner.index().is_monotonic_increasing()
                || self.inner.index().is_monotonic_decreasing();
            if !is_sorted {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "truncate requires a sorted index",
                ));
            }
            let b = match before {
                Some(obj) => Some(py_to_index_label(obj)?),
                None => None,
            };
            let a = match after {
                Some(obj) => Some(py_to_index_label(obj)?),
                None => None,
            };
            if let (Some(b_lbl), Some(a_lbl)) = (&b, &a) {
                if self.inner.index().is_monotonic_increasing() && b_lbl > a_lbl {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                        "Truncate: {a_lbl} must be after {b_lbl}"
                    )));
                }
            }
            let res = self
                .inner
                .truncate(b.as_ref(), a.as_ref())
                .map_err(frame_error_to_py)?;
            Ok(PyDataFrame { inner: res })
        } else {
            let cols = self.inner.column_names();
            let is_sorted = cols.windows(2).all(|w| w[0] <= w[1]);
            if !is_sorted {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "truncate requires a sorted index",
                ));
            }
            let b_str = before.map(|obj| obj.extract::<String>()).transpose()?;
            let a_str = after.map(|obj| obj.extract::<String>()).transpose()?;
            if let (Some(b), Some(a)) = (&b_str, &a_str) {
                if b > a {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                        "Truncate: {a} must be after {b}"
                    )));
                }
            }
            let start = match &b_str {
                Some(b) => cols
                    .iter()
                    .position(|c| c.as_str() >= b.as_str())
                    .unwrap_or(cols.len()),
                None => 0,
            };
            let end = match &a_str {
                Some(a) => cols
                    .iter()
                    .rposition(|c| c.as_str() <= a.as_str())
                    .map(|i| i + 1)
                    .unwrap_or(0),
                None => cols.len(),
            };
            let selected_cols: Vec<&str> = if start >= end {
                Vec::new()
            } else {
                cols[start..end].iter().map(|s| s.as_str()).collect()
            };
            let res = self
                .inner
                .select_columns(&selected_cols)
                .map_err(frame_error_to_py)?;
            Ok(PyDataFrame { inner: res })
        }
    }

    #[pyo3(signature = (prefix, axis=None))]
    fn add_prefix(&self, prefix: &str, axis: Option<&Bound<'_, PyAny>>) -> PyResult<PyDataFrame> {
        let axis_idx = match axis {
            None => 1,
            Some(a) => {
                if let Ok(i) = a.extract::<i64>() {
                    match i {
                        0 => 0,
                        1 => 1,
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "No axis named {other} for object type DataFrame"
                            )));
                        }
                    }
                } else if let Ok(s) = a.extract::<String>() {
                    match s.as_str() {
                        "index" | "rows" => 0,
                        "columns" => 1,
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "No axis named {other} for object type DataFrame"
                            )));
                        }
                    }
                } else {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "axis must be 0, 1, 'index', or 'columns'",
                    ));
                }
            }
        };
        let res = self
            .inner
            .add_prefix_axis(prefix, axis_idx)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

    #[pyo3(signature = (suffix, axis=None))]
    fn add_suffix(&self, suffix: &str, axis: Option<&Bound<'_, PyAny>>) -> PyResult<PyDataFrame> {
        let axis_idx = match axis {
            None => 1,
            Some(a) => {
                if let Ok(i) = a.extract::<i64>() {
                    match i {
                        0 => 0,
                        1 => 1,
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "No axis named {other} for object type DataFrame"
                            )));
                        }
                    }
                } else if let Ok(s) = a.extract::<String>() {
                    match s.as_str() {
                        "index" | "rows" => 0,
                        "columns" => 1,
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "No axis named {other} for object type DataFrame"
                            )));
                        }
                    }
                } else {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "axis must be 0, 1, 'index', or 'columns'",
                    ));
                }
            }
        };
        let res = self
            .inner
            .add_suffix_axis(suffix, axis_idx)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

    fn first_valid_index(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        match self.inner.first_valid_index() {
            Some(l) => index_label_to_py(py, &l),
            None => Ok(py.None()),
        }
    }

    fn last_valid_index(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        match self.inner.last_valid_index() {
            Some(l) => index_label_to_py(py, &l),
            None => Ok(py.None()),
        }
    }

    fn equals(&self, other: &PyDataFrame) -> bool {
        self.inner.equals(&other.inner)
    }

    fn pop(&mut self, item: &str) -> PyResult<PySeries> {
        let (series, remaining) = self.inner.pop(item).map_err(frame_error_to_py)?;
        self.inner = remaining;
        Ok(PySeries { inner: series })
    }

    #[pyo3(signature = (axis=None))]
    fn squeeze(&self, py: Python<'_>, axis: Option<&Bound<'_, PyAny>>) -> PyResult<Py<PyAny>> {
        let parsed_axis = match axis {
            None => None,
            Some(a) => {
                if let Ok(i) = a.extract::<i64>() {
                    match i {
                        0 => Some(0),
                        1 => Some(1),
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "No axis named {other} for object type DataFrame"
                            )));
                        }
                    }
                } else if let Ok(s) = a.extract::<String>() {
                    match s.as_str() {
                        "index" | "rows" => Some(0),
                        "columns" => Some(1),
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "No axis named {other} for object type DataFrame"
                            )));
                        }
                    }
                } else {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "axis must be 0, 1, 'index', or 'columns'",
                    ));
                }
            }
        };

        let num_rows = self.inner.len();
        let num_cols = self.inner.column_names().len();

        match parsed_axis {
            None => {
                if num_rows == 1 && num_cols == 1 {
                    let col_name = self.inner.column_names()[0];
                    let col = self.column_series(col_name)?;
                    let s = col.inner.column().values()[0].clone();
                    scalar_to_py(py, &s)
                } else if num_cols == 1 {
                    let col_name = self.inner.column_names()[0];
                    let col = self.column_series(col_name)?;
                    Ok(Py::new(py, col)?.into_any())
                } else if num_rows == 1 {
                    match self.inner.squeeze_to_series(0) {
                        Ok(s) => Ok(Py::new(py, PySeries { inner: s })?.into_any()),
                        Err(_) => Ok(Py::new(
                            py,
                            PyDataFrame {
                                inner: self.inner.clone(),
                            },
                        )?
                        .into_any()),
                    }
                } else {
                    Ok(Py::new(
                        py,
                        PyDataFrame {
                            inner: self.inner.clone(),
                        },
                    )?
                    .into_any())
                }
            }
            Some(0) => {
                if num_rows == 1 {
                    match self.inner.squeeze_to_series(0) {
                        Ok(s) => Ok(Py::new(py, PySeries { inner: s })?.into_any()),
                        Err(_) => Ok(Py::new(
                            py,
                            PyDataFrame {
                                inner: self.inner.clone(),
                            },
                        )?
                        .into_any()),
                    }
                } else {
                    Ok(Py::new(
                        py,
                        PyDataFrame {
                            inner: self.inner.clone(),
                        },
                    )?
                    .into_any())
                }
            }
            Some(1) => {
                if num_cols == 1 {
                    let col_name = self.inner.column_names()[0];
                    let col = self.column_series(col_name)?;
                    Ok(Py::new(py, col)?.into_any())
                } else {
                    Ok(Py::new(
                        py,
                        PyDataFrame {
                            inner: self.inner.clone(),
                        },
                    )?
                    .into_any())
                }
            }
            _ => unreachable!(),
        }
    }

    fn keys(&self) -> Vec<String> {
        self.columns()
    }

    fn items(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        let mut list = Vec::with_capacity(self.inner.column_names().len());
        for col_name in self.inner.column_names() {
            let s = self.column_series(col_name)?;
            let py_s = Py::new(py, s)?;
            list.push((col_name.as_str(), py_s).into_pyobject(py)?);
        }
        Ok(PyList::new(py, list)?.into_any().unbind())
    }

    fn iterrows(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        let rows = self.inner.iterrows();
        let mut list = Vec::with_capacity(rows.len());
        for (label, row_data) in rows {
            let py_label = index_label_to_py(py, &label)?;
            let mut col_items = Vec::with_capacity(row_data.len());
            let mut col_labels = Vec::with_capacity(row_data.len());
            for (col_name, val) in row_data {
                col_labels.push(IndexLabel::Utf8(col_name.to_string()));
                col_items.push(val);
            }
            let s = Series::from_values(label.to_string(), col_labels, col_items)
                .map_err(frame_error_to_py)?;
            let py_s = Py::new(py, PySeries { inner: s })?;
            list.push(pyo3::types::PyTuple::new(py, &[py_label, py_s.into_any()])?);
        }
        Ok(PyList::new(py, list)?.into_any().unbind())
    }

    #[pyo3(signature = (index=true, name="Pandas"))]
    fn itertuples(&self, py: Python<'_>, index: bool, name: Option<&str>) -> PyResult<Py<PyAny>> {
        let tuples = self.inner.itertuples();
        let col_names = self.inner.column_names();
        let named_type = if let Some(n) = name {
            if let Ok(collections) = py.import("collections") {
                let mut field_names = Vec::new();
                if index {
                    field_names.push("Index".to_string());
                }
                for c in &col_names {
                    let mut sanitized: String = c
                        .chars()
                        .map(|ch| if ch.is_alphanumeric() { ch } else { '_' })
                        .collect();
                    if sanitized.is_empty() || sanitized.chars().next().unwrap().is_ascii_digit() {
                        sanitized = format!("_{sanitized}");
                    }
                    field_names.push(sanitized);
                }
                collections
                    .call_method1("namedtuple", (n, field_names))
                    .ok()
            } else {
                None
            }
        } else {
            None
        };

        let mut list = Vec::with_capacity(tuples.len());
        for (label, vals) in tuples {
            let mut py_vals = Vec::with_capacity(vals.len() + usize::from(index));
            if index {
                py_vals.push(index_label_to_py(py, &label)?);
            }
            for v in &vals {
                py_vals.push(scalar_to_py(py, v)?);
            }
            let row_obj = if let Some(ref nt) = named_type {
                let tup = pyo3::types::PyTuple::new(py, &py_vals)?;
                if let Ok(inst) = nt.call1(&tup) {
                    inst.into_any().unbind()
                } else {
                    tup.into_any().unbind()
                }
            } else {
                pyo3::types::PyTuple::new(py, &py_vals)?.into_any().unbind()
            };
            list.push(row_obj);
        }
        Ok(PyList::new(py, list)?.into_any().unbind())
    }

    #[pyo3(signature = (axis=None, inplace=false, limit=None, downcast=None))]
    fn pad(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        limit: Option<isize>,
        downcast: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PyDataFrame> {
        self.ffill(axis, inplace, limit, downcast, None)
    }

    #[pyo3(signature = (axis=None, inplace=false, limit=None, downcast=None))]
    fn backfill(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        limit: Option<isize>,
        downcast: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PyDataFrame> {
        self.bfill(axis, inplace, limit, downcast, None)
    }

    fn agg(&self, py: Python<'_>, func: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        if let Ok(name) = func.extract::<String>() {
            match name.as_str() {
                "sum" => Ok(Py::new(
                    py,
                    PySeries {
                        inner: self
                            .sum_internal(0, true, false)
                            .map_err(frame_error_to_py)?,
                    },
                )?
                .into_any()),
                "mean" => Ok(Py::new(
                    py,
                    PySeries {
                        inner: self
                            .mean_internal(0, true, false)
                            .map_err(frame_error_to_py)?,
                    },
                )?
                .into_any()),
                "min" => Ok(Py::new(
                    py,
                    PySeries {
                        inner: self
                            .min_internal(0, true, false)
                            .map_err(frame_error_to_py)?,
                    },
                )?
                .into_any()),
                "max" => Ok(Py::new(
                    py,
                    PySeries {
                        inner: self
                            .max_internal(0, true, false)
                            .map_err(frame_error_to_py)?,
                    },
                )?
                .into_any()),
                "std" => Ok(Py::new(
                    py,
                    PySeries {
                        inner: self
                            .std_internal(0, true, 1, false)
                            .map_err(frame_error_to_py)?,
                    },
                )?
                .into_any()),
                "var" => Ok(Py::new(
                    py,
                    PySeries {
                        inner: self
                            .var_internal(0, true, 1, false)
                            .map_err(frame_error_to_py)?,
                    },
                )?
                .into_any()),
                "count" => Ok(Py::new(
                    py,
                    PySeries {
                        inner: self.count_internal(0, false).map_err(frame_error_to_py)?,
                    },
                )?
                .into_any()),
                "median" => Ok(Py::new(
                    py,
                    PySeries {
                        inner: self
                            .median_internal(0, true, false)
                            .map_err(frame_error_to_py)?,
                    },
                )?
                .into_any()),
                "prod" | "product" => Ok(Py::new(
                    py,
                    PySeries {
                        inner: self
                            .prod_internal(0, true, false)
                            .map_err(frame_error_to_py)?,
                    },
                )?
                .into_any()),
                "sem" => Ok(Py::new(
                    py,
                    PySeries {
                        inner: self
                            .sem_internal(0, true, 1, false)
                            .map_err(frame_error_to_py)?,
                    },
                )?
                .into_any()),
                "skew" => Ok(Py::new(
                    py,
                    PySeries {
                        inner: self.skew_internal(0, false).map_err(frame_error_to_py)?,
                    },
                )?
                .into_any()),
                "kurt" | "kurtosis" => Ok(Py::new(
                    py,
                    PySeries {
                        inner: self.kurt_internal(0, false).map_err(frame_error_to_py)?,
                    },
                )?
                .into_any()),
                other => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "Unsupported agg function '{other}'"
                ))),
            }
        } else if let Ok(dict) = func.extract::<std::collections::HashMap<String, Vec<String>>>() {
            let res = self.inner.agg(&dict).map_err(frame_error_to_py)?;
            Ok(Py::new(py, PyDataFrame { inner: res })?.into_any())
        } else {
            Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "func must be a string or dict of column -> list of functions",
            ))
        }
    }

    fn aggregate(&self, py: Python<'_>, func: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        self.agg(py, func)
    }

    #[pyo3(signature = (index=true))]
    fn memory_usage(&self, index: bool) -> PyResult<PySeries> {
        let res = self
            .inner
            .memory_usage_with_options(index, false)
            .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: res })
    }

    #[getter]
    fn axes(&self) -> Vec<Py<PyAny>> {
        Python::attach(|py| {
            let idx = Py::new(py, self.index()).ok()?;
            let cols = PyList::new(py, self.columns()).ok()?;
            Some(vec![idx.into_any(), cols.into_any().unbind()])
        })
        .unwrap_or_default()
    }

    #[getter]
    fn attrs<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyDict>> {
        Ok(PyDict::new(py))
    }

    fn r#bool(&self) -> PyResult<bool> {
        let (r, c) = self.inner.shape();
        if r == 1 && c == 1 {
            let col = self.column_series(self.inner.column_names()[0])?;
            col.r#bool()
        } else {
            Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "The truth value of a DataFrame is ambiguous. Use a.empty, a.bool(), a.item(), a.any() or a.all().",
            ))
        }
    }

    fn combine_first(&self, other: &PyDataFrame) -> PyResult<PyDataFrame> {
        let res = self
            .inner
            .combine_first(&other.inner)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

    #[pyo3(signature = (other, join="outer"))]
    fn align(&self, other: &PyDataFrame, join: &str) -> PyResult<(PyDataFrame, PyDataFrame)> {
        let mode = match join {
            "outer" => AlignMode::Outer,
            "inner" => AlignMode::Inner,
            "left" => AlignMode::Left,
            "right" => AlignMode::Right,
            _ => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "Invalid join mode '{join}'"
                )));
            }
        };
        let (df1, df2) = self
            .inner
            .align(&other.inner, mode)
            .map_err(frame_error_to_py)?;
        Ok((PyDataFrame { inner: df1 }, PyDataFrame { inner: df2 }))
    }

    fn compare(&self, other: &PyDataFrame) -> PyResult<PyDataFrame> {
        let res = self
            .inner
            .compare(&other.inner)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

    fn convert_dtypes(&self) -> PyResult<PyDataFrame> {
        let res = self.inner.convert_dtypes().map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

    fn at_time(&self, time: &str) -> PyResult<PyDataFrame> {
        let res = self.inner.at_time(time).map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

    fn between_time(&self, start: &str, end: &str) -> PyResult<PyDataFrame> {
        let res = self
            .inner
            .between_time(start, end)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

    #[pyo3(signature = (label, subset=None))]
    fn asof(&self, label: &Bound<'_, PyAny>, subset: Option<Vec<String>>) -> PyResult<PySeries> {
        let lbl = py_to_index_label(label)?;
        let subset_refs: Option<Vec<&str>> = subset
            .as_ref()
            .map(|s| s.iter().map(String::as_str).collect());
        let res = self
            .inner
            .asof(&lbl, subset_refs.as_deref())
            .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: res })
    }

    #[pyo3(signature = (other, axis=None, drop=false, method="pearson", numeric_only=false))]
    fn corrwith(
        &self,
        other: &Bound<'_, PyAny>,
        axis: Option<&Bound<'_, PyAny>>,
        drop: bool,
        method: Option<&str>,
        numeric_only: bool,
    ) -> PyResult<PySeries> {
        let m = method.unwrap_or("pearson");
        if !matches!(m, "pearson" | "spearman" | "kendall") {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "unsupported correlation method: '{m}'"
            )));
        }
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        let calc_corr = |s1: &Series, s2: &Series| -> Result<f64, FrameError> {
            match m {
                "pearson" => s1.corr(s2),
                "spearman" => s1.corr_spearman(s2),
                "kendall" => s1.corr_kendall(s2),
                _ => unreachable!(),
            }
        };

        if let Ok(other_s) = other.extract::<PyRef<PySeries>>() {
            if !matches!(
                other_s.inner.dtype(),
                DType::Int64 | DType::Float64 | DType::Bool
            ) {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "could not convert non-numeric series to float",
                ));
            }
            if ax == 0 {
                let mut labels = Vec::new();
                let mut values = Vec::new();
                for col_name in self.inner.column_names() {
                    let col = match self.inner.column(col_name) {
                        Some(c) => c,
                        None => continue,
                    };
                    let is_num = matches!(col.dtype(), DType::Int64 | DType::Float64 | DType::Bool);
                    if !is_num {
                        if numeric_only {
                            continue;
                        }
                        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                            "Could not convert non-numeric column '{col_name}' to float"
                        )));
                    }
                    let s_col =
                        Series::new(col_name.clone(), self.inner.index().clone(), col.clone())
                            .map_err(frame_error_to_py)?;
                    let r = calc_corr(&s_col, &other_s.inner).map_err(frame_error_to_py)?;
                    if drop && r.is_nan() {
                        continue;
                    }
                    labels.push(IndexLabel::Utf8(col_name.clone()));
                    values.push(Scalar::Float64(r));
                }
                let res = Series::from_values("corrwith".to_string(), labels, values)
                    .map_err(frame_error_to_py)?;
                return Ok(PySeries { inner: res });
            } else {
                let mut cols_to_use = Vec::new();
                for col_name in self.inner.column_names() {
                    let col = match self.inner.column(col_name) {
                        Some(c) => c,
                        None => continue,
                    };
                    let is_num = matches!(col.dtype(), DType::Int64 | DType::Float64 | DType::Bool);
                    if !is_num {
                        if numeric_only {
                            continue;
                        }
                        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                            "Could not convert non-numeric column '{col_name}' to float"
                        )));
                    }
                    cols_to_use.push(col_name.to_string());
                }
                let col_labels: Vec<IndexLabel> = cols_to_use
                    .iter()
                    .map(|c| IndexLabel::Utf8(c.clone()))
                    .collect();
                let mut labels = Vec::new();
                let mut values = Vec::new();
                for (row_idx, row_label) in self.inner.index().labels().iter().enumerate() {
                    let mut row_vals = Vec::with_capacity(cols_to_use.len());
                    for c in &cols_to_use {
                        if let Some(col) = self.inner.column(c) {
                            row_vals.push(col.values()[row_idx].clone());
                        }
                    }
                    let row_s =
                        Series::from_values("row".to_string(), col_labels.clone(), row_vals)
                            .map_err(frame_error_to_py)?;
                    let r = calc_corr(&row_s, &other_s.inner).map_err(frame_error_to_py)?;
                    if drop && r.is_nan() {
                        continue;
                    }
                    labels.push(row_label.clone());
                    values.push(Scalar::Float64(r));
                }
                let res = Series::from_values("corrwith".to_string(), labels, values)
                    .map_err(frame_error_to_py)?;
                return Ok(PySeries { inner: res });
            }
        }

        if let Ok(other_df) = other.extract::<PyRef<PyDataFrame>>() {
            if ax == 0 {
                let mut all_cols: Vec<String> = self
                    .inner
                    .column_names()
                    .into_iter()
                    .map(|s| s.to_string())
                    .collect();
                for c in other_df.inner.column_names() {
                    if !all_cols.contains(&c.to_string()) {
                        all_cols.push(c.to_string());
                    }
                }
                let mut labels = Vec::new();
                let mut values = Vec::new();
                for col_name in &all_cols {
                    let col1 = self.inner.column(col_name);
                    let col2 = other_df.inner.column(col_name);
                    let is_num1 = col1.is_none_or(|c| {
                        matches!(c.dtype(), DType::Int64 | DType::Float64 | DType::Bool)
                    });
                    let is_num2 = col2.is_none_or(|c| {
                        matches!(c.dtype(), DType::Int64 | DType::Float64 | DType::Bool)
                    });
                    if !is_num1 || !is_num2 {
                        if numeric_only {
                            continue;
                        }
                        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                            "Could not convert non-numeric column '{col_name}' to float"
                        )));
                    }
                    let r = match (col1, col2) {
                        (Some(c1), Some(c2)) => {
                            let s1 = Series::new(
                                col_name.clone(),
                                self.inner.index().clone(),
                                c1.clone(),
                            )
                            .map_err(frame_error_to_py)?;
                            let s2 = Series::new(
                                col_name.clone(),
                                other_df.inner.index().clone(),
                                c2.clone(),
                            )
                            .map_err(frame_error_to_py)?;
                            calc_corr(&s1, &s2).map_err(frame_error_to_py)?
                        }
                        _ => f64::NAN,
                    };
                    if drop && r.is_nan() {
                        continue;
                    }
                    labels.push(IndexLabel::Utf8(col_name.clone()));
                    values.push(Scalar::Float64(r));
                }
                let res = Series::from_values("corrwith".to_string(), labels, values)
                    .map_err(frame_error_to_py)?;
                return Ok(PySeries { inner: res });
            } else {
                let mut shared_cols = Vec::new();
                for c in self.inner.column_names() {
                    if let Some(other_c) = other_df.inner.column(c) {
                        let self_c = self.inner.column(c).unwrap();
                        let s_num =
                            matches!(self_c.dtype(), DType::Int64 | DType::Float64 | DType::Bool);
                        let o_num =
                            matches!(other_c.dtype(), DType::Int64 | DType::Float64 | DType::Bool);
                        if !s_num || !o_num {
                            if numeric_only {
                                continue;
                            }
                            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                                "Could not convert non-numeric column '{c}' to float"
                            )));
                        }
                        shared_cols.push(c.to_string());
                    }
                }
                let col_labels: Vec<IndexLabel> = shared_cols
                    .iter()
                    .map(|c| IndexLabel::Utf8(c.clone()))
                    .collect();
                let other_pos = other_df.inner.index().position_map_first();
                let self_pos = self.inner.index().position_map_first();
                let mut all_labels = self.inner.index().labels().to_vec();
                for lbl in other_df.inner.index().labels() {
                    if !all_labels.contains(lbl) {
                        all_labels.push(lbl.clone());
                    }
                }
                let mut labels = Vec::new();
                let mut values = Vec::new();

                for label in &all_labels {
                    let r = match (self_pos.get(label), other_pos.get(label)) {
                        (Some(&row1), Some(&row2)) => {
                            if shared_cols.len() < 2 {
                                f64::NAN
                            } else {
                                let r1_vals: Vec<Scalar> = shared_cols
                                    .iter()
                                    .map(|c| self.inner.column(c).unwrap().values()[row1].clone())
                                    .collect();
                                let r2_vals: Vec<Scalar> = shared_cols
                                    .iter()
                                    .map(|c| {
                                        other_df.inner.column(c).unwrap().values()[row2].clone()
                                    })
                                    .collect();
                                let s1 = Series::from_values(
                                    "r1".to_string(),
                                    col_labels.clone(),
                                    r1_vals,
                                )
                                .map_err(frame_error_to_py)?;
                                let s2 = Series::from_values(
                                    "r2".to_string(),
                                    col_labels.clone(),
                                    r2_vals,
                                )
                                .map_err(frame_error_to_py)?;
                                calc_corr(&s1, &s2).unwrap_or(f64::NAN)
                            }
                        }
                        _ => f64::NAN,
                    };
                    if drop && r.is_nan() {
                        continue;
                    }
                    labels.push(label.clone());
                    values.push(Scalar::Float64(r));
                }
                let res = Series::from_values("corrwith".to_string(), labels, values)
                    .map_err(frame_error_to_py)?;
                return Ok(PySeries { inner: res });
            }
        }

        Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
            "other must be a Series or DataFrame",
        ))
    }

    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (func, axis=None, raw=false, result_type=None, *args, **kwargs))]
    fn apply(
        &self,
        py: Python<'_>,
        func: &Bound<'_, PyAny>,
        axis: Option<&Bound<'_, PyAny>>,
        raw: bool,
        result_type: Option<&str>,
        args: &Bound<'_, PyTuple>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Py<PyAny>> {
        // raw=True hands `func` numpy arrays where this passes Series, and
        // result_type reshapes the output; neither is implemented yet.
        unsupported_params(
            "DataFrame.apply",
            &[("raw", !raw), ("result_type", result_type.is_none())],
        )?;
        let ax: usize = match axis {
            Some(a) => {
                if let Ok(i) = a.extract::<usize>() {
                    i
                } else if let Ok(s) = a.extract::<String>() {
                    match s.to_ascii_lowercase().as_str() {
                        "0" | "index" | "rows" => 0,
                        "1" | "columns" => 1,
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "No axis named {other} for object type DataFrame"
                            )));
                        }
                    }
                } else {
                    0
                }
            }
            None => 0,
        };

        if ax == 0 {
            let mut res_items = Vec::new();
            for col_name in self.inner.column_names() {
                let s = self.column_series(col_name)?;
                let py_s = Py::new(py, s)?;
                let res = if args.is_empty() {
                    let t = PyTuple::new(py, &[py_s.into_any()])?;
                    func.call(t, kwargs)?
                } else {
                    let mut full_args = Vec::with_capacity(1 + args.len());
                    full_args.push(py_s.into_any());
                    for a in args.iter() {
                        full_args.push(a.into_any().unbind());
                    }
                    let t = PyTuple::new(py, &full_args)?;
                    func.call(t, kwargs)?
                };
                res_items.push((col_name.to_string(), res));
            }

            let mut scalars = Vec::new();
            let mut all_scalars = true;
            for (_, r) in &res_items {
                if let Ok(sc) = py_to_scalar(py, r) {
                    scalars.push(sc);
                } else {
                    all_scalars = false;
                    break;
                }
            }
            if all_scalars {
                let labels: Vec<IndexLabel> = res_items
                    .iter()
                    .map(|(n, _)| IndexLabel::Utf8(n.clone()))
                    .collect();
                let s = Series::from_values("", labels, scalars).map_err(frame_error_to_py)?;
                return Ok(Py::new(py, PySeries { inner: s })?.into_any());
            }

            let mut series_cols = Vec::new();
            let mut all_series = true;
            for (_, r) in &res_items {
                if let Ok(py_ser) = r.extract::<PyRef<PySeries>>() {
                    series_cols.push(py_ser.inner.clone());
                } else {
                    all_series = false;
                    break;
                }
            }
            if all_series && !series_cols.is_empty() {
                let idx = series_cols[0].index().clone();
                let mut col_map = BTreeMap::new();
                let mut col_order = Vec::with_capacity(res_items.len());
                for (i, (name, _)) in res_items.iter().enumerate() {
                    col_map.insert(name.clone(), series_cols[i].column().clone());
                    col_order.push(name.clone());
                }
                let df = DataFrame::new_with_column_order(idx, col_map, col_order)
                    .map_err(frame_error_to_py)?;
                return Ok(Py::new(py, PyDataFrame { inner: df })?.into_any());
            }

            let list = PyList::new(py, res_items.into_iter().map(|(_, r)| r))?;
            return Ok(list.into_any().unbind());
        }

        // ax == 1: Apply row-by-row
        let (nrows, ncols) = self.inner.shape();
        let col_names = self.inner.column_names();
        let col_labels: Vec<IndexLabel> = col_names
            .iter()
            .map(|n| IndexLabel::Utf8(n.to_string()))
            .collect();
        let mut cols_vals = Vec::with_capacity(ncols);
        for pos in 0..ncols {
            let col = self.inner.column_at(pos).expect("col in bounds");
            cols_vals.push(col.values());
        }

        let mut row_results = Vec::with_capacity(nrows);
        for r in 0..nrows {
            let row_scalars: Vec<Scalar> = (0..ncols).map(|c| cols_vals[c][r].clone()).collect();
            let row_label = self
                .inner
                .index()
                .labels()
                .get(r)
                .cloned()
                .unwrap_or(IndexLabel::Int64(r as i64));
            let s = Series::from_values(row_label.to_string(), col_labels.clone(), row_scalars)
                .map_err(frame_error_to_py)?;
            let py_s = Py::new(py, PySeries { inner: s })?;
            let res = if args.is_empty() {
                let t = PyTuple::new(py, &[py_s.into_any()])?;
                func.call(t, kwargs)?
            } else {
                let mut full_args = Vec::with_capacity(1 + args.len());
                full_args.push(py_s.into_any());
                for a in args.iter() {
                    full_args.push(a.into_any().unbind());
                }
                let t = PyTuple::new(py, &full_args)?;
                func.call(t, kwargs)?
            };
            row_results.push(res);
        }

        let mut scalars = Vec::with_capacity(nrows);
        let mut all_scalars = true;
        for r in &row_results {
            if let Ok(sc) = py_to_scalar(py, r) {
                scalars.push(sc);
            } else {
                all_scalars = false;
                break;
            }
        }
        if all_scalars {
            let s = Series::from_values("", self.inner.index().labels().to_vec(), scalars)
                .map_err(frame_error_to_py)?;
            return Ok(Py::new(py, PySeries { inner: s })?.into_any());
        }

        let mut series_rows = Vec::new();
        let mut all_series = true;
        for r in &row_results {
            if let Ok(py_ser) = r.extract::<PyRef<PySeries>>() {
                series_rows.push(py_ser.inner.clone());
            } else {
                all_series = false;
                break;
            }
        }
        if all_series && !series_rows.is_empty() {
            let new_col_names: Vec<String> = series_rows[0]
                .index()
                .labels()
                .iter()
                .map(|l| l.to_string())
                .collect();
            let mut col_data: Vec<Vec<Scalar>> = (0..new_col_names.len())
                .map(|_| Vec::with_capacity(nrows))
                .collect();
            for s in &series_rows {
                let vals = s.column().values();
                for (ci, v) in vals.iter().enumerate() {
                    if ci < col_data.len() {
                        col_data[ci].push(v.clone());
                    }
                }
            }
            let mut col_map = BTreeMap::new();
            for (ci, name) in new_col_names.iter().enumerate() {
                let col = Column::from_values(col_data[ci].clone()).map_err(column_error_to_py)?;
                col_map.insert(name.clone(), col);
            }
            let df = DataFrame::new_with_column_order(
                self.inner.index().clone(),
                col_map,
                new_col_names,
            )
            .map_err(frame_error_to_py)?;
            return Ok(Py::new(py, PyDataFrame { inner: df })?.into_any());
        }

        let mut dict_rows = Vec::new();
        let mut all_dicts = true;
        for r in &row_results {
            if let Ok(d) = r.cast::<PyDict>() {
                dict_rows.push(d);
            } else {
                all_dicts = false;
                break;
            }
        }
        if all_dicts && !dict_rows.is_empty() {
            let mut seen_keys = Vec::new();
            for d in &dict_rows {
                for k in d.keys() {
                    if let Ok(k_str) = k.extract::<String>() {
                        if !seen_keys.contains(&k_str) {
                            seen_keys.push(k_str);
                        }
                    }
                }
            }
            let mut col_map = BTreeMap::new();
            for k in &seen_keys {
                let mut col_vals = Vec::with_capacity(nrows);
                for d in &dict_rows {
                    if let Some(item) = d.get_item(k)? {
                        col_vals.push(py_to_scalar(py, &item)?);
                    } else {
                        col_vals.push(Scalar::Float64(f64::NAN));
                    }
                }
                let col = Column::from_values(col_vals).map_err(column_error_to_py)?;
                col_map.insert(k.clone(), col);
            }
            let df =
                DataFrame::new_with_column_order(self.inner.index().clone(), col_map, seen_keys)
                    .map_err(frame_error_to_py)?;
            return Ok(Py::new(py, PyDataFrame { inner: df })?.into_any());
        }

        let list = PyList::new(py, row_results)?;
        Ok(list.into_any().unbind())
    }

    fn applymap(&self, py: Python<'_>, func: &Bound<'_, PyAny>) -> PyResult<PyDataFrame> {
        let (nrows, ncols) = self.inner.shape();
        let col_names = self.inner.column_names();
        let mut col_map = BTreeMap::new();
        let mut column_order = Vec::with_capacity(ncols);
        for col_name in &col_names {
            let s = self.column_series(col_name)?;
            let vals = s.inner.column().values();
            let mut out = Vec::with_capacity(nrows);
            for v in vals {
                let py_v = scalar_to_py(py, v)?;
                let res = func.call1((py_v,))?;
                out.push(py_to_scalar(py, &res)?);
            }
            let col = Column::from_values(out)
                .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
            column_order.push((*col_name).clone());
            col_map.insert((*col_name).clone(), col);
        }
        let df =
            DataFrame::new_with_column_order(self.inner.index().clone(), col_map, column_order)
                .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    fn map(&self, py: Python<'_>, func: &Bound<'_, PyAny>) -> PyResult<PyDataFrame> {
        self.applymap(py, func)
    }

    fn dot(&self, other: &PyDataFrame) -> PyResult<PyDataFrame> {
        let df = self.inner.dot(&other.inner).map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    #[pyo3(signature = (cond, other=None, inplace=false, axis=None, level=None))]
    fn r#where(
        &mut self,
        py: Python<'_>,
        cond: &Bound<'_, PyAny>,
        other: Option<&Bound<'_, PyAny>>,
        inplace: Option<bool>,
        axis: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PyDataFrame>> {
        unsupported_params("DataFrame.where", &[("level", level.is_none())])?;
        let ax = parse_axis_param_for_type(axis, "DataFrame")?;
        let cond_norm = normalize_df_cond(py, &self.inner, cond)?;
        let other_norm = normalize_df_other(py, &self.inner, other)?;
        let res_inner = execute_df_where(&self.inner, &cond_norm, &other_norm, ax)?;
        if inplace.unwrap_or(false) {
            self.inner = res_inner;
            Ok(None)
        } else {
            Ok(Some(PyDataFrame { inner: res_inner }))
        }
    }

    #[pyo3(signature = (cond, other=None, inplace=false, axis=None, level=None))]
    fn mask(
        &mut self,
        py: Python<'_>,
        cond: &Bound<'_, PyAny>,
        other: Option<&Bound<'_, PyAny>>,
        inplace: Option<bool>,
        axis: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PyDataFrame>> {
        unsupported_params("DataFrame.mask", &[("level", level.is_none())])?;
        let ax = parse_axis_param_for_type(axis, "DataFrame")?;
        let cond_norm = normalize_df_cond(py, &self.inner, cond)?;
        let other_norm = normalize_df_other(py, &self.inner, other)?;
        let res_inner = execute_df_mask(&self.inner, &cond_norm, &other_norm, ax)?;
        if inplace.unwrap_or(false) {
            self.inner = res_inner;
            Ok(None)
        } else {
            Ok(Some(PyDataFrame { inner: res_inner }))
        }
    }

    #[pyo3(signature = (func, *args, **kwargs))]
    fn pipe<'py>(
        &self,
        py: Python<'py>,
        func: &Bound<'py, PyAny>,
        args: &Bound<'py, pyo3::types::PyTuple>,
        kwargs: Option<&Bound<'py, PyDict>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        if let Ok(tup) = func.cast::<pyo3::types::PyTuple>()
            && tup.len() == 2
        {
            let f = tup.get_item(0)?;
            let kw_name = tup.get_item(1)?.extract::<String>()?;
            let kw = kwargs.cloned().unwrap_or_else(|| PyDict::new(py));
            kw.set_item(kw_name, self.clone())?;
            return f.call(args, Some(&kw));
        }
        let mut full_args = Vec::with_capacity(args.len() + 1);
        full_args.push(Py::new(py, self.clone())?.into_any());
        for item in args.iter() {
            full_args.push(item.clone().unbind());
        }
        let tuple_args = pyo3::types::PyTuple::new(py, full_args)?;
        func.call(tuple_args, kwargs)
    }

    #[pyo3(signature = (items=None, like=None, regex=None, axis=None))]
    fn filter(
        &self,
        items: Option<Vec<String>>,
        like: Option<&str>,
        regex: Option<&str>,
        axis: Option<usize>,
    ) -> PyResult<PyDataFrame> {
        let ax = axis.unwrap_or(1);
        let items_refs: Option<Vec<&str>> = items
            .as_ref()
            .map(|v| v.iter().map(String::as_str).collect());
        let df = self
            .inner
            .filter_axis(items_refs.as_deref(), like, regex, ax)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    #[pyo3(signature = (key, default=None))]
    fn get<'py>(
        &self,
        py: Python<'py>,
        key: &Bound<'py, PyAny>,
        default: Option<&Bound<'py, PyAny>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        if let Ok(col_name) = key.extract::<String>() {
            let col_names = self.inner.column_names();
            let matches: Vec<&str> = col_names
                .iter()
                .filter(|c| c.as_str() == col_name.as_str())
                .map(|s| s.as_str())
                .collect();
            if matches.len() > 1 {
                let frame = self
                    .inner
                    .select_columns(&matches)
                    .map_err(frame_error_to_py)?;
                let py_df = Py::new(py, PyDataFrame { inner: frame })?;
                return Ok(py_df.into_bound(py).into_any());
            } else if matches.len() == 1 {
                if let Some(col) = self.inner.column(&col_name) {
                    let s = Series::new(col_name, self.inner.index().clone(), col.clone())
                        .map_err(frame_error_to_py)?;
                    let py_s = Py::new(py, PySeries { inner: s })?;
                    return Ok(py_s.into_bound(py).into_any());
                }
            }
        } else if let Ok(cols) = key.extract::<Vec<String>>() {
            let mut all_exist = true;
            for col in &cols {
                if self.inner.column(col).is_none() {
                    all_exist = false;
                    break;
                }
            }
            if all_exist {
                let refs: Vec<&str> = cols.iter().map(String::as_str).collect();
                let frame = self
                    .inner
                    .select_columns(&refs)
                    .map_err(frame_error_to_py)?;
                let py_df = Py::new(py, PyDataFrame { inner: frame })?;
                return Ok(py_df.into_bound(py).into_any());
            }
        }
        Ok(default.cloned().unwrap_or_else(|| py.None().into_bound(py)))
    }

    fn first(&self, offset: &str) -> PyResult<PyDataFrame> {
        let df = self.inner.first_offset(offset).map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    fn last(&self, offset: &str) -> PyResult<PyDataFrame> {
        let df = self.inner.last_offset(offset).map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    /// pandas' `DataFrame.reindex`. `method` fills absent row labels from the
    /// neighbouring source row and `fill_value` fills absent row labels and
    /// new columns (fvsao.5: both used to be dropped through `**kwargs`).
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (labels=None, *, index=None, columns=None, axis=None, method=None, copy=None, level=None, fill_value=None, limit=None, tolerance=None))]
    fn reindex(
        &self,
        py: Python<'_>,
        labels: Option<&Bound<'_, PyAny>>,
        index: Option<&Bound<'_, PyAny>>,
        columns: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        method: Option<&str>,
        copy: Option<bool>,
        level: Option<&Bound<'_, PyAny>>,
        fill_value: Option<&Bound<'_, PyAny>>,
        limit: Option<usize>,
        tolerance: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PyDataFrame> {
        // copy= only lets pandas share buffers; a new frame satisfies it.
        let _ = copy;
        let fill = match fill_value.filter(|fv| !fv.is_none()) {
            Some(fv) => Some(py_to_scalar(py, fv)?),
            None => None,
        };
        unsupported_params(
            "DataFrame.reindex",
            &[
                ("level", level.is_none()),
                ("limit", limit.is_none()),
                ("tolerance", tolerance.is_none()),
                (
                    "method",
                    method.is_none() || (fill.is_none() && columns.is_none()),
                ),
            ],
        )?;
        let mut res = self.inner.clone();
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        let target_index = index.or_else(|| labels.filter(|_| ax == 0));
        if let Some(idx_obj) = target_index {
            let row_labels = if let Ok(py_idx) = idx_obj.extract::<PyRef<'_, PyIndex>>() {
                py_idx.inner.labels().to_vec()
            } else if let Ok(list) = idx_obj.cast::<PyList>() {
                let mut lbls = Vec::with_capacity(list.len());
                for item in list.iter() {
                    lbls.push(py_to_index_label(&item)?);
                }
                lbls
            } else {
                return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                    "reindex expects Index or list of labels",
                ));
            };
            res = match (method, &fill) {
                (Some(m), _) => res.reindex_with_method(row_labels, m),
                (None, Some(f)) => res.reindex_fill(row_labels, f.clone()),
                (None, None) => res.reindex(row_labels),
            }
            .map_err(frame_error_to_py)?;
        }
        let target_columns = columns.or_else(|| labels.filter(|_| ax == 1));
        if let Some(col_obj) = target_columns {
            let col_names: Vec<String> = if let Ok(list) = col_obj.cast::<PyList>() {
                let mut cols = Vec::with_capacity(list.len());
                for item in list.iter() {
                    cols.push(item.extract::<String>()?);
                }
                cols
            } else {
                col_obj.extract::<Vec<String>>()?
            };
            let str_cols: Vec<&str> = col_names.iter().map(String::as_str).collect();
            res = res.reindex_columns(&str_cols).map_err(frame_error_to_py)?;
            if let Some(f) = &fill {
                for name in col_names.iter().filter(|c| self.inner.column(c).is_none()) {
                    let filled = Column::from_values(vec![f.clone(); res.len()]).map_err(|e| {
                        PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string())
                    })?;
                    res = res
                        .with_column(name.clone(), filled)
                        .map_err(frame_error_to_py)?;
                }
            }
        }
        Ok(PyDataFrame { inner: res })
    }

    #[pyo3(signature = (include=None, exclude=None))]
    fn select_dtypes(
        &self,
        include: Option<&Bound<'_, PyAny>>,
        exclude: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PyDataFrame> {
        let extract_str_vec = |obj: Option<&Bound<'_, PyAny>>| -> PyResult<Vec<String>> {
            match obj {
                None => Ok(Vec::new()),
                Some(o) => {
                    if let Ok(s) = o.extract::<String>() {
                        Ok(vec![s])
                    } else if let Ok(list) = o.cast::<PyList>() {
                        let mut v = Vec::with_capacity(list.len());
                        for item in list.iter() {
                            v.push(item.extract::<String>()?);
                        }
                        Ok(v)
                    } else {
                        o.extract::<Vec<String>>()
                    }
                }
            }
        };
        let inc = extract_str_vec(include)?;
        let exc = extract_str_vec(exclude)?;
        let inc_refs: Vec<&str> = inc.iter().map(String::as_str).collect();
        let exc_refs: Vec<&str> = exc.iter().map(String::as_str).collect();
        let df = self
            .inner
            .select_dtypes_by_name(&inc_refs, &exc_refs)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    #[pyo3(signature = (loc, column, value, allow_duplicates=false))]
    fn insert(
        &mut self,
        py: Python<'_>,
        loc: usize,
        column: &str,
        value: &Bound<'_, PyAny>,
        allow_duplicates: bool,
    ) -> PyResult<()> {
        let col = if let Ok(py_s) = value.extract::<PyRef<'_, PySeries>>() {
            py_s.inner.column().clone()
        } else if let Ok(list) = value.cast::<PyList>() {
            let mut scalars = Vec::with_capacity(list.len());
            for item in list.iter() {
                scalars.push(py_to_scalar(py, &item)?);
            }
            Column::from_values(scalars)
                .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?
        } else {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "insert value must be a Series or list",
            ));
        };
        self.inner = self
            .inner
            .insert_allow_duplicates(loc, column, col, allow_duplicates)
            .map_err(frame_error_to_py)?;
        Ok(())
    }

    #[pyo3(signature = (other, on=None, how="left", lsuffix="", rsuffix="", sort=false))]
    fn join(
        &self,
        other: &Bound<'_, PyAny>,
        on: Option<&str>,
        how: &str,
        lsuffix: &str,
        rsuffix: &str,
        sort: bool,
    ) -> PyResult<PyDataFrame> {
        let right_df = if let Ok(odf) = other.extract::<PyRef<'_, PyDataFrame>>() {
            odf.inner.clone()
        } else if let Ok(os) = other.extract::<PyRef<'_, PySeries>>() {
            let col_name = os.inner.name();
            let mut map = BTreeMap::new();
            map.insert(col_name.to_string(), os.inner.column().clone());
            DataFrame::new_with_column_order(
                os.inner.index().clone(),
                map,
                vec![col_name.to_string()],
            )
            .map_err(frame_error_to_py)?
        } else {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "join expects DataFrame or Series",
            ));
        };
        let join_type = match how {
            "inner" => fp_join::JoinType::Inner,
            "left" => fp_join::JoinType::Left,
            "right" => fp_join::JoinType::Right,
            "outer" => fp_join::JoinType::Outer,
            _ => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "unknown how={how:?}; expected inner/left/right/outer"
                )));
            }
        };
        let options = fp_join::MergeExecutionOptions {
            indicator_name: None,
            validate_mode: None,
            suffixes: if lsuffix.is_empty() && rsuffix.is_empty() {
                None
            } else {
                Some([
                    if lsuffix.is_empty() {
                        None
                    } else {
                        Some(lsuffix.to_string())
                    },
                    if rsuffix.is_empty() {
                        None
                    } else {
                        Some(rsuffix.to_string())
                    },
                ])
            },
            sort,
        };
        if let Some(on_col) = on {
            let merged = fp_join::merge_dataframes_on_with_options(
                &self.inner,
                &right_df,
                &[on_col],
                &[on_col],
                join_type,
                options,
            )
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
            let df =
                DataFrame::new_with_column_order(merged.index, merged.columns, merged.column_order)
                    .map_err(frame_error_to_py)?;
            Ok(PyDataFrame { inner: df })
        } else {
            let make_indexed_df = |df: &DataFrame| -> PyResult<DataFrame> {
                let idx_col = Column::from_values(
                    df.index()
                        .labels()
                        .iter()
                        .map(|l| Scalar::Utf8(l.to_string()))
                        .collect(),
                )
                .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
                let mut cols = df.columns().clone();
                let mut order: Vec<String> =
                    df.column_names().iter().map(|s| (*s).clone()).collect();
                cols.insert("__fp_join_idx__".to_string(), idx_col);
                order.push("__fp_join_idx__".to_string());
                DataFrame::new_with_column_order(df.index().clone(), cols, order)
                    .map_err(frame_error_to_py)
            };
            let left_with_idx = make_indexed_df(&self.inner)?;
            let right_with_idx = make_indexed_df(&right_df)?;
            let merged = fp_join::merge_dataframes_on_with_options(
                &left_with_idx,
                &right_with_idx,
                &["__fp_join_idx__"],
                &["__fp_join_idx__"],
                join_type,
                options,
            )
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
            let mut final_cols = merged.columns;
            final_cols.remove("__fp_join_idx__");
            if !lsuffix.is_empty() {
                final_cols.remove(&format!("__fp_join_idx__{lsuffix}"));
            }
            if !rsuffix.is_empty() {
                final_cols.remove(&format!("__fp_join_idx__{rsuffix}"));
            }
            let final_order: Vec<String> = merged
                .column_order
                .into_iter()
                .filter(|c| !c.starts_with("__fp_join_idx__"))
                .collect();
            let df = DataFrame::new_with_column_order(merged.index, final_cols, final_order)
                .map_err(frame_error_to_py)?;
            Ok(PyDataFrame { inner: df })
        }
    }

    #[pyo3(signature = (copy=None))]
    fn infer_objects(&self, copy: Option<bool>) -> PyResult<PyDataFrame> {
        // copy= only lets pandas share buffers; a new frame satisfies it.
        let _ = copy;
        let df = self.inner.infer_objects().map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    /// pandas' `DataFrame.interpolate` down each column (fvsao.5: `method`
    /// and every option used to be dropped, so any call interpolated
    /// linearly).
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (method="linear", *, axis=None, limit=None, inplace=false, limit_direction=None, limit_area=None, downcast=None, **kwargs))]
    fn interpolate(
        &self,
        method: &str,
        axis: Option<&Bound<'_, PyAny>>,
        limit: Option<usize>,
        inplace: bool,
        limit_direction: Option<&str>,
        limit_area: Option<&str>,
        downcast: Option<&Bound<'_, PyAny>>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PyDataFrame> {
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        unsupported_params(
            "DataFrame.interpolate",
            &[("axis", ax == 0), ("downcast", downcast.is_none())],
        )?;
        engine_kwargs("DataFrame.interpolate", "scipy", kwargs)?;
        if inplace {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "inplace=True is not supported",
            ));
        }
        if !Series::interpolate_supports(method, limit_direction, limit_area) {
            return Err(not_implemented(&format!(
                "DataFrame.interpolate(method='{method}') with limit_direction or limit_area"
            )));
        }
        let df = self
            .inner
            .interpolate_with(method, limit, limit_direction, limit_area)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    fn stack(&self) -> PyResult<PyDataFrame> {
        let df = self.inner.stack().map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    fn unstack(&self) -> PyResult<PyDataFrame> {
        let df = self.inner.unstack().map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    #[pyo3(signature = (level=0))]
    fn droplevel(&self, level: usize) -> PyResult<PyDataFrame> {
        let df = self
            .inner
            .droplevel_level(level)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    /// Swaps the last two row levels, pandas' default; other levels and the
    /// column axis are not supported yet (they were ignored).
    #[pyo3(signature = (i=-2, j=-1, axis=0))]
    fn swaplevel(&self, i: isize, j: isize, axis: usize) -> PyResult<PyDataFrame> {
        unsupported_params(
            "DataFrame.swaplevel",
            &[("i", i == -2), ("j", j == -1), ("axis", axis == 0)],
        )?;
        Ok(PyDataFrame {
            inner: self.inner.swaplevel(),
        })
    }

    #[pyo3(signature = (indices, axis=None, **kwargs))]
    fn take(
        &self,
        indices: Vec<i64>,
        axis: Option<&Bound<'_, PyAny>>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PyDataFrame> {
        numpy_compat_kwargs("take", kwargs)?;
        let axis = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        let df = self.inner.take(&indices, axis).map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    /// pandas' `DataFrame.explode(column, ignore_index=False)` expands
    /// list-like cells and leaves every scalar, strings included, as it is. A
    /// frankenpandas cell is always a scalar, so the rows stay as they are.
    /// This used to split strings on a `sep` keyword pandas does not have,
    /// turning "Smith, John" into two rows (fvsao.5).
    #[pyo3(signature = (column, ignore_index=false))]
    fn explode(&self, column: &Bound<'_, PyAny>, ignore_index: bool) -> PyResult<PyDataFrame> {
        let col_names = extract_col_names_flexible(Some(column))?;
        if col_names.is_empty() {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "column must be nonempty",
            ));
        }
        if let Some(missing) = col_names.iter().find(|c| self.inner.column(c).is_none()) {
            return Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(
                missing.clone(),
            ));
        }
        let out = if ignore_index {
            self.inner.reset_index(true).map_err(frame_error_to_py)?
        } else {
            self.inner.clone()
        };
        Ok(PyDataFrame { inner: out })
    }

    fn info(&self) -> String {
        self.inner.info()
    }

    fn update(&mut self, other: &PyDataFrame) -> PyResult<()> {
        self.inner = self.inner.update(&other.inner).map_err(frame_error_to_py)?;
        Ok(())
    }

    #[pyo3(signature = (subset=None, normalize=false, sort=true, ascending=false, dropna=true))]
    fn value_counts(
        &self,
        subset: Option<&Bound<'_, PyAny>>,
        normalize: bool,
        sort: bool,
        ascending: bool,
        dropna: bool,
    ) -> PyResult<PySeries> {
        unsupported_params(
            "DataFrame.value_counts",
            &[("sort", sort), ("dropna", dropna)],
        )?;
        let cols = extract_col_names_flexible(subset)?;
        let mut s = if cols.is_empty() {
            self.inner.value_counts()
        } else {
            let refs: Vec<&str> = cols.iter().map(|s| s.as_str()).collect();
            self.inner.value_counts_subset(&refs)
        }
        .map_err(frame_error_to_py)?;

        if ascending {
            let mut labels = s.index().labels().to_vec();
            let mut values = s.column().values().to_vec();
            labels.reverse();
            values.reverse();
            s = Series::from_values(s.name().to_string(), labels, values)
                .map_err(frame_error_to_py)?;
        }

        if normalize {
            let total: f64 = s
                .column()
                .values()
                .iter()
                .filter_map(|v| v.to_f64().ok())
                .sum();
            if total > 0.0 {
                let norm_values: Vec<Scalar> = s
                    .column()
                    .values()
                    .iter()
                    .map(|v| match v.to_f64() {
                        Ok(cnt) => Scalar::Float64(cnt / total),
                        Err(_) => Scalar::Null(NullKind::NaN),
                    })
                    .collect();
                s = Series::from_values(
                    "proportion".to_string(),
                    s.index().labels().to_vec(),
                    norm_values,
                )
                .map_err(frame_error_to_py)?;
            }
        }

        Ok(PySeries { inner: s })
    }

    #[pyo3(signature = (axis=None, dropna=true))]
    fn nunique(&self, axis: Option<&Bound<'_, PyAny>>, dropna: bool) -> PyResult<PySeries> {
        let ax = parse_axis_param(axis)?;
        let s = self
            .inner
            .nunique_axis_with_dropna(ax, dropna)
            .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    /// pandas' `DataFrame.xs` on the row index. The row comes back as a
    /// one-row frame, pandas' drop_level=False shape, whatever drop_level
    /// says (the Series return is fvsao.7's).
    #[pyo3(signature = (key, axis=None, level=None, drop_level=true))]
    fn xs(
        &self,
        key: &Bound<'_, PyAny>,
        axis: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
        drop_level: bool,
    ) -> PyResult<PyDataFrame> {
        let _ = drop_level;
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        unsupported_params(
            "DataFrame.xs",
            &[("axis", ax == 0), ("level", level.is_none())],
        )?;
        let lbl = py_to_index_label(key)?;
        let df = self.inner.xs(&lbl).map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    /// pandas' `DataFrame.rename_axis` for the row index (`mapper` or
    /// `index`); naming the columns axis is not supported yet.
    #[pyo3(signature = (mapper=None, *, index=None, columns=None, axis=None, copy=None, inplace=false))]
    fn rename_axis(
        &self,
        mapper: Option<&str>,
        index: Option<&str>,
        columns: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        copy: Option<bool>,
        inplace: bool,
    ) -> PyResult<PyDataFrame> {
        // copy= only lets pandas share buffers; a new frame satisfies it.
        let _ = copy;
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        unsupported_params(
            "DataFrame.rename_axis",
            &[
                ("columns", columns.is_none()),
                ("axis", ax == 0),
                ("inplace", !inplace),
            ],
        )?;
        let name = mapper.or(index).unwrap_or("");
        let df = self.inner.rename_axis(name).map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    #[pyo3(signature = (labels, *, axis=None, copy=None))]
    fn set_axis(
        &self,
        labels: &Bound<'_, PyAny>,
        axis: Option<&Bound<'_, PyAny>>,
        copy: Option<bool>,
    ) -> PyResult<PyDataFrame> {
        // copy= only lets pandas share buffers; a new frame satisfies it.
        let _ = copy;
        let axis_idx = match axis {
            None => 0,
            Some(a) => {
                if let Ok(i) = a.extract::<i64>() {
                    match i {
                        0 => 0,
                        1 => 1,
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "No axis named {other} for object type DataFrame"
                            )));
                        }
                    }
                } else if let Ok(s) = a.extract::<String>() {
                    match s.as_str() {
                        "index" | "rows" => 0,
                        "columns" => 1,
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "No axis named {other} for object type DataFrame"
                            )));
                        }
                    }
                } else {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "axis must be 0, 1, 'index', or 'columns'",
                    ));
                }
            }
        };
        let lbls = if let Ok(py_idx) = labels.extract::<PyRef<'_, PyIndex>>() {
            py_idx.inner.labels().to_vec()
        } else if let Ok(list) = labels.cast::<PyList>() {
            let mut v = Vec::with_capacity(list.len());
            for item in list.iter() {
                v.push(py_to_index_label(&item)?);
            }
            v
        } else {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "set_axis expects Index or list of labels",
            ));
        };
        let df = self
            .inner
            .set_axis(lbls, axis_idx)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    fn divmod(
        &self,
        py: Python<'_>,
        other: &Bound<'_, PyAny>,
    ) -> PyResult<(PyDataFrame, PyDataFrame)> {
        let q = self.floordiv(py, other, None, None, None)?;
        let r = self.r#mod(py, other, None, None, None)?;
        Ok((q, r))
    }

    fn rdivmod(
        &self,
        py: Python<'_>,
        other: &Bound<'_, PyAny>,
    ) -> PyResult<(PyDataFrame, PyDataFrame)> {
        let q = self.rfloordiv(py, other, None, None, None)?;
        let r = self.rmod(py, other, None, None, None)?;
        Ok((q, r))
    }

    #[pyo3(signature = (*args, **kwargs))]
    fn boxplot(
        &self,
        py: Python<'_>,
        args: &Bound<'_, pyo3::types::PyTuple>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PyPlotResult> {
        let _ = py;
        plot_args(args, kwargs)?;
        let spec = self.inner.boxplot().map_err(frame_error_to_py)?;
        let svg = spec.to_svg().map_err(frame_error_to_py)?;
        Ok(PyPlotResult {
            svg,
            kind: "box".to_string(),
        })
    }

    #[pyo3(signature = (other, func, fill_value=None, overwrite=true))]
    fn combine(
        &self,
        py: Python<'_>,
        other: &PyDataFrame,
        func: &Bound<'_, PyAny>,
        fill_value: Option<&Bound<'_, PyAny>>,
        overwrite: Option<bool>,
    ) -> PyResult<PyDataFrame> {
        if self.inner.is_empty() && !other.inner.is_empty() {
            return Ok(PyDataFrame {
                inner: other.inner.clone(),
            });
        }
        let fill_scalar = match fill_value {
            Some(fv) if !fv.is_none() => Some(py_to_scalar(py, fv)?),
            _ => None,
        };
        let overwrite_val = overwrite.unwrap_or(true);

        let (aligned_left, aligned_right) = self
            .inner
            .align(&other.inner, AlignMode::Outer)
            .map_err(frame_error_to_py)?;

        let new_columns: Vec<String> = if self.inner.column_names() == other.inner.column_names() {
            self.inner.column_names().into_iter().cloned().collect()
        } else {
            let mut cols_set = std::collections::BTreeSet::new();
            for col in self.inner.column_names() {
                cols_set.insert((*col).clone());
            }
            for col in other.inner.column_names() {
                cols_set.insert((*col).clone());
            }
            cols_set.into_iter().collect::<Vec<_>>()
        };

        let mut result_cols: BTreeMap<String, Column> = BTreeMap::new();
        for col in &new_columns {
            let left_col = aligned_left.column(col).unwrap();
            let right_col = aligned_right.column(col).unwrap();

            let other_all_missing = right_col.values().iter().all(Scalar::is_missing);
            if !overwrite_val && other_all_missing {
                result_cols.insert(col.clone(), left_col.clone());
                continue;
            }

            let left_col_filled = if let Some(fv) = &fill_scalar {
                let vals: Vec<Scalar> = left_col
                    .values()
                    .iter()
                    .map(|v| {
                        if v.is_missing() {
                            fv.clone()
                        } else {
                            v.clone()
                        }
                    })
                    .collect();
                Column::from_values(vals)
                    .map_err(fp_frame::FrameError::Column)
                    .map_err(frame_error_to_py)?
            } else {
                left_col.clone()
            };

            let right_col_filled = if let Some(fv) = &fill_scalar {
                let vals: Vec<Scalar> = right_col
                    .values()
                    .iter()
                    .map(|v| {
                        if v.is_missing() {
                            fv.clone()
                        } else {
                            v.clone()
                        }
                    })
                    .collect();
                Column::from_values(vals)
                    .map_err(fp_frame::FrameError::Column)
                    .map_err(frame_error_to_py)?
            } else {
                right_col.clone()
            };

            let left_s = Series::new(col.clone(), aligned_left.index().clone(), left_col_filled)
                .map_err(frame_error_to_py)?;
            let right_s = Series::new(col.clone(), aligned_right.index().clone(), right_col_filled)
                .map_err(frame_error_to_py)?;

            let py_s1 = Py::new(py, PySeries { inner: left_s })?;
            let py_s2 = Py::new(py, PySeries { inner: right_s })?;

            let call_res = func.call1((py_s1, py_s2))?;

            if let Ok(py_res_s) = call_res.extract::<PyRef<'_, PySeries>>() {
                let res_inner = &py_res_s.inner;
                if res_inner.len() == aligned_left.len() {
                    result_cols.insert(col.clone(), res_inner.column().clone());
                } else {
                    let reindexed = res_inner
                        .reindex(aligned_left.index().labels().to_vec())
                        .map_err(frame_error_to_py)?;
                    result_cols.insert(col.clone(), reindexed.column().clone());
                }
            } else if let Ok(py_list) = call_res.extract::<Vec<Bound<'_, PyAny>>>() {
                let mut scalars = Vec::with_capacity(py_list.len());
                for item in py_list {
                    scalars.push(py_to_scalar(py, &item)?);
                }
                let res_col = Column::from_values(scalars)
                    .map_err(fp_frame::FrameError::Column)
                    .map_err(frame_error_to_py)?;
                result_cols.insert(col.clone(), res_col);
            } else if let Ok(sc) = py_to_scalar(py, &call_res) {
                let res_col = Column::from_values(vec![sc; aligned_left.len()])
                    .map_err(fp_frame::FrameError::Column)
                    .map_err(frame_error_to_py)?;
                result_cols.insert(col.clone(), res_col);
            } else {
                return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                    "Unsupported return type from combine func for column '{}'",
                    col
                )));
            }
        }

        let final_df = DataFrame::new_with_column_order(
            aligned_left.index().clone(),
            result_cols,
            new_columns,
        )
        .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: final_df })
    }

