#[pyfunction(name = "is_dtype_equal")]
fn api_is_dtype_equal(source: &Bound<'_, PyAny>, target: &Bound<'_, PyAny>) -> bool {
    if source.is(target) {
        return true;
    }
    if let (Ok(s1), Ok(s2)) = (source.extract::<String>(), target.extract::<String>()) {
        return s1 == s2;
    }
    false
}

