#[pyclass(name = "Interval", from_py_object)]
#[derive(Clone, Debug, PartialEq)]
pub struct PyInterval {
    #[pyo3(get)]
    pub left: f64,
    #[pyo3(get)]
    pub right: f64,
    #[pyo3(get)]
    pub closed: String,
}

#[pymethods]
impl PyInterval {
    #[new]
    #[pyo3(signature = (left, right, closed="right"))]
    fn new(left: f64, right: f64, closed: Option<&str>) -> PyResult<Self> {
        let closed_str = closed.unwrap_or("right");
        if !["right", "left", "both", "neither"].contains(&closed_str) {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "closed must be one of 'right', 'left', 'both', 'neither'",
            ));
        }
        Ok(Self {
            left,
            right,
            closed: closed_str.to_string(),
        })
    }

    #[getter]
    fn length(&self) -> f64 {
        self.right - self.left
    }

    #[getter]
    fn mid(&self) -> f64 {
        (self.left + self.right) / 2.0
    }

    fn __contains__(&self, val: f64) -> bool {
        match self.closed.as_str() {
            "right" => val > self.left && val <= self.right,
            "left" => val >= self.left && val < self.right,
            "both" => val >= self.left && val <= self.right,
            "neither" => val > self.left && val < self.right,
            _ => false,
        }
    }

    fn __repr__(&self) -> String {
        format!(
            "Interval({}, {}, closed='{}')",
            self.left, self.right, self.closed
        )
    }

    fn __str__(&self) -> String {
        let (l_bracket, r_bracket) = match self.closed.as_str() {
            "right" => ('(', ']'),
            "left" => ('[', ')'),
            "both" => ('[', ']'),
            _ => ('(', ')'),
        };
        format!("{}{}, {}{}", l_bracket, self.left, self.right, r_bracket)
    }
}

#[pyclass(name = "IntervalIndex", from_py_object)]
#[derive(Clone, Debug)]
pub struct PyIntervalIndex {
    pub intervals: Vec<PyInterval>,
    pub name: Option<String>,
}

#[pymethods]
impl PyIntervalIndex {
    #[new]
    #[pyo3(signature = (data=None, name=None))]
    fn new(data: Option<&Bound<'_, PyAny>>, name: Option<&str>) -> PyResult<Self> {
        let mut intervals = Vec::new();
        if let Some(d) = data {
            if let Ok(list) = d.extract::<Vec<PyInterval>>() {
                intervals = list;
            } else if let Ok(seq) = d.cast::<pyo3::types::PySequence>() {
                let len = seq.len()?;
                for i in 0..len {
                    let item = seq.get_item(i)?;
                    if let Ok(iv) = item.extract::<PyInterval>() {
                        intervals.push(iv);
                    }
                }
            }
        }
        Ok(Self {
            intervals,
            name: name.map(str::to_string),
        })
    }

    #[classmethod]
    #[pyo3(signature = (breaks, closed="right", name=None))]
    fn from_breaks(
        _cls: &Bound<'_, pyo3::types::PyType>,
        breaks: Vec<f64>,
        closed: Option<&str>,
        name: Option<&str>,
    ) -> PyResult<Self> {
        let closed_str = closed.unwrap_or("right");
        if breaks.len() < 2 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "breaks must have at least 2 elements",
            ));
        }
        let mut intervals = Vec::with_capacity(breaks.len() - 1);
        for i in 0..(breaks.len() - 1) {
            intervals.push(PyInterval::new(breaks[i], breaks[i + 1], Some(closed_str))?);
        }
        Ok(Self {
            intervals,
            name: name.map(str::to_string),
        })
    }

    #[classmethod]
    #[pyo3(signature = (data, closed="right", name=None))]
    fn from_tuples(
        _cls: &Bound<'_, pyo3::types::PyType>,
        data: Vec<(f64, f64)>,
        closed: Option<&str>,
        name: Option<&str>,
    ) -> PyResult<Self> {
        let closed_str = closed.unwrap_or("right");
        let mut intervals = Vec::with_capacity(data.len());
        for (left, right) in data {
            intervals.push(PyInterval::new(left, right, Some(closed_str))?);
        }
        Ok(Self {
            intervals,
            name: name.map(str::to_string),
        })
    }

    #[classmethod]
    #[pyo3(signature = (left, right, closed="right", name=None))]
    fn from_arrays(
        _cls: &Bound<'_, pyo3::types::PyType>,
        left: Vec<f64>,
        right: Vec<f64>,
        closed: Option<&str>,
        name: Option<&str>,
    ) -> PyResult<Self> {
        let closed_str = closed.unwrap_or("right");
        if left.len() != right.len() {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "left and right arrays must have equal length",
            ));
        }
        let mut intervals = Vec::with_capacity(left.len());
        for (l, r) in left.into_iter().zip(right) {
            intervals.push(PyInterval::new(l, r, Some(closed_str))?);
        }
        Ok(Self {
            intervals,
            name: name.map(str::to_string),
        })
    }

    #[getter]
    fn name(&self) -> Option<String> {
        self.name.clone()
    }

    #[getter]
    fn length(&self) -> usize {
        self.intervals.len()
    }

    fn __len__(&self) -> usize {
        self.intervals.len()
    }

    fn __getitem__(&self, idx: isize) -> PyResult<PyInterval> {
        let len = self.intervals.len() as isize;
        let pos = if idx < 0 { idx + len } else { idx };
        if pos < 0 || pos >= len {
            return Err(PyErr::new::<pyo3::exceptions::PyIndexError, _>(
                "index out of range",
            ));
        }
        Ok(self.intervals[pos as usize].clone())
    }

    fn __repr__(&self) -> String {
        format!("IntervalIndex({:?})", self.intervals)
    }

    #[getter]
    fn closed(&self) -> String {
        self.intervals
            .first()
            .map_or("right", |iv| iv.closed.as_str())
            .to_string()
    }

    #[getter]
    fn closed_left(&self) -> bool {
        self.to_rust().closed_left()
    }

    #[getter]
    fn closed_right(&self) -> bool {
        self.to_rust().closed_right()
    }

    #[getter]
    fn open_left(&self) -> bool {
        self.to_rust().open_left()
    }

    #[getter]
    fn open_right(&self) -> bool {
        self.to_rust().open_right()
    }

    #[getter]
    fn is_non_overlapping_monotonic(&self) -> bool {
        self.to_rust().is_non_overlapping_monotonic()
    }

    #[getter]
    fn dtype(&self) -> String {
        self.to_rust().dtype()
    }

    #[getter]
    fn is_unique(&self) -> bool {
        self.to_rust().is_unique()
    }

    #[getter]
    fn is_monotonic_increasing(&self) -> bool {
        self.to_rust().is_monotonic_increasing()
    }

    #[getter]
    fn is_monotonic_decreasing(&self) -> bool {
        self.to_rust().is_monotonic_decreasing()
    }

    #[getter]
    fn left(&self) -> PyIndex {
        let labels = self
            .intervals
            .iter()
            .map(|iv| IndexLabel::Float64(fp_index::OrderedF64(iv.left)))
            .collect();
        PyIndex {
            inner: Index::new(labels),
        }
    }

    #[getter]
    fn right(&self) -> PyIndex {
        let labels = self
            .intervals
            .iter()
            .map(|iv| IndexLabel::Float64(fp_index::OrderedF64(iv.right)))
            .collect();
        PyIndex {
            inner: Index::new(labels),
        }
    }

    #[getter]
    fn mid(&self) -> PyIndex {
        let labels = self
            .intervals
            .iter()
            .map(|iv| IndexLabel::Float64(fp_index::OrderedF64(iv.mid())))
            .collect();
        PyIndex {
            inner: Index::new(labels),
        }
    }

    #[getter]
    fn is_overlapping(&self) -> bool {
        self.to_rust().is_overlapping()
    }

    fn contains(&self, point: f64) -> Vec<bool> {
        self.to_rust().contains(point)
    }

    fn get_loc(&self, point: f64) -> PyResult<usize> {
        self.to_rust()
            .get_loc(point)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyKeyError, _>(e.to_string()))
    }

    #[pyo3(signature = (target))]
    fn get_indexer(&self, target: &Bound<'_, PyAny>) -> PyResult<Vec<i64>> {
        let rust_idx = self.to_rust();
        let points: Vec<f64> = if let Ok(v) = target.extract::<Vec<f64>>() {
            v
        } else if let Ok(seq) = target.cast::<pyo3::types::PySequence>() {
            let len = seq.len()?;
            let mut pts = Vec::with_capacity(len);
            for i in 0..len {
                pts.push(seq.get_item(i)?.extract::<f64>()?);
            }
            pts
        } else {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "target must be a sequence of floats",
            ));
        };
        Ok(rust_idx
            .get_indexer(&points)
            .into_iter()
            .map(|opt| opt.map_or(-1, |u| u as i64))
            .collect())
    }

    fn get_indexer_for(&self, target: &Bound<'_, PyAny>) -> PyResult<Vec<i64>> {
        self.get_indexer(target)
    }

    fn to_tuples(&self) -> Vec<(f64, f64)> {
        self.to_rust().to_tuples()
    }

    fn to_list(&self) -> Vec<PyInterval> {
        self.intervals.clone()
    }

    fn tolist(&self) -> Vec<PyInterval> {
        self.intervals.clone()
    }

    fn set_closed(&self, closed: &str) -> PyResult<Self> {
        let mut intervals = Vec::with_capacity(self.intervals.len());
        for iv in &self.intervals {
            intervals.push(PyInterval::new(iv.left, iv.right, Some(closed))?);
        }
        Ok(Self {
            intervals,
            name: self.name.clone(),
        })
    }

    fn overlaps(&self, other: &PyInterval) -> Vec<bool> {
        let other_closed = match other.closed.as_str() {
            "left" => fp_types::IntervalClosed::Left,
            "both" => fp_types::IntervalClosed::Both,
            "neither" => fp_types::IntervalClosed::Neither,
            _ => fp_types::IntervalClosed::Right,
        };
        let other_iv = fp_types::Interval::new(other.left, other.right, other_closed);
        self.to_rust().overlaps(&other_iv)
    }

    fn to_index(&self) -> PyIndex {
        PyIndex {
            inner: self.to_rust().to_index(),
        }
    }
}

impl PyIntervalIndex {
    pub fn to_rust(&self) -> fp_index::IntervalIndex {
        let values: Vec<fp_types::Interval> = self
            .intervals
            .iter()
            .map(|iv| {
                let closed = match iv.closed.as_str() {
                    "left" => fp_types::IntervalClosed::Left,
                    "both" => fp_types::IntervalClosed::Both,
                    "neither" => fp_types::IntervalClosed::Neither,
                    _ => fp_types::IntervalClosed::Right,
                };
                fp_types::Interval::new(iv.left, iv.right, closed)
            })
            .collect();
        let closed = values
            .first()
            .map_or(fp_types::IntervalClosed::Right, |iv| iv.closed);
        fp_index::IntervalIndex::new_with_options(values, closed, self.name.clone())
    }

    pub fn from_rust(rust_idx: &fp_index::IntervalIndex) -> Self {
        let intervals = rust_idx
            .values()
            .iter()
            .map(|iv| PyInterval {
                left: iv.left,
                right: iv.right,
                closed: iv.closed.to_string(),
            })
            .collect();
        Self {
            intervals,
            name: rust_idx.name().map(str::to_string),
        }
    }
}

#[pyclass(name = "Categorical", from_py_object)]
#[derive(Clone, Debug)]
pub struct PyCategorical {
    pub categories_list: Vec<String>,
    #[pyo3(get)]
    pub codes: Vec<i64>,
    #[pyo3(get)]
    pub ordered: bool,
}

#[pymethods]
impl PyCategorical {
    #[new]
    #[pyo3(signature = (values, categories=None, ordered=false))]
    fn new(
        values: &Bound<'_, PyAny>,
        categories: Option<Vec<String>>,
        ordered: Option<bool>,
    ) -> PyResult<Self> {
        let ordered = ordered.unwrap_or(false);
        let seq = values.cast::<pyo3::types::PySequence>()?;
        let len = seq.len()?;
        let mut raw_vals = Vec::with_capacity(len);
        for i in 0..len {
            let item = seq.get_item(i)?;
            raw_vals.push(item.str()?.to_str()?.to_string());
        }
        let cats = if let Some(c) = categories {
            c
        } else {
            let mut set = HashSet::new();
            let mut unique_cats = Vec::new();
            for v in &raw_vals {
                if set.insert(v.clone()) {
                    unique_cats.push(v.clone());
                }
            }
            unique_cats.sort();
            unique_cats
        };
        let cat_map: HashMap<&str, i64> = cats
            .iter()
            .enumerate()
            .map(|(i, s)| (s.as_str(), i as i64))
            .collect();
        let codes: Vec<i64> = raw_vals
            .iter()
            .map(|v| cat_map.get(v.as_str()).copied().unwrap_or(-1))
            .collect();

        Ok(Self {
            categories_list: cats,
            codes,
            ordered,
        })
    }

    #[getter]
    fn categories(&self) -> PyIndex {
        let labels = self
            .categories_list
            .iter()
            .map(|s| IndexLabel::Utf8(s.clone()))
            .collect();
        PyIndex {
            inner: Index::new(labels),
        }
    }

    #[getter]
    fn dtype(&self) -> PyCategoricalDtype {
        PyCategoricalDtype {
            categories: Some(self.categories_list.clone()),
            ordered: self.ordered,
        }
    }

    fn __repr__(&self) -> String {
        format!(
            "Categorical(categories={:?}, ordered={}, length={})",
            self.categories_list,
            self.ordered,
            self.codes.len()
        )
    }

    fn __len__(&self) -> usize {
        self.codes.len()
    }
}

#[pyclass(name = "DateOffset", from_py_object)]
#[derive(Clone, Debug, PartialEq)]
pub struct PyDateOffset {
    #[pyo3(get)]
    pub n: i64,
    #[pyo3(get)]
    pub years: i64,
    #[pyo3(get)]
    pub months: i64,
    #[pyo3(get)]
    pub weeks: i64,
    #[pyo3(get)]
    pub days: i64,
    #[pyo3(get)]
    pub hours: i64,
    #[pyo3(get)]
    pub minutes: i64,
    #[pyo3(get)]
    pub seconds: i64,
    #[pyo3(get)]
    pub microseconds: i64,
    #[pyo3(get)]
    pub nanoseconds: i64,
}

impl Default for PyDateOffset {
    fn default() -> Self {
        Self {
            n: 1,
            years: 0,
            months: 0,
            weeks: 0,
            days: 0,
            hours: 0,
            minutes: 0,
            seconds: 0,
            microseconds: 0,
            nanoseconds: 0,
        }
    }
}

#[pymethods]
impl PyDateOffset {
    #[new]
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (n=1, years=0, months=0, weeks=0, days=0, hours=0, minutes=0, seconds=0, microseconds=0, nanoseconds=0))]
    fn new(
        n: Option<i64>,
        years: Option<i64>,
        months: Option<i64>,
        weeks: Option<i64>,
        days: Option<i64>,
        hours: Option<i64>,
        minutes: Option<i64>,
        seconds: Option<i64>,
        microseconds: Option<i64>,
        nanoseconds: Option<i64>,
    ) -> Self {
        Self {
            n: n.unwrap_or(1),
            years: years.unwrap_or(0),
            months: months.unwrap_or(0),
            weeks: weeks.unwrap_or(0),
            days: days.unwrap_or(0),
            hours: hours.unwrap_or(0),
            minutes: minutes.unwrap_or(0),
            seconds: seconds.unwrap_or(0),
            microseconds: microseconds.unwrap_or(0),
            nanoseconds: nanoseconds.unwrap_or(0),
        }
    }

    fn nanos(&self) -> i64 {
        let mut total_nanos = self.nanoseconds;
        total_nanos += self.microseconds * 1_000;
        total_nanos += self.seconds * 1_000_000_000;
        total_nanos += self.minutes * 60 * 1_000_000_000;
        total_nanos += self.hours * 3600 * 1_000_000_000;
        total_nanos += self.days * 86400 * 1_000_000_000;
        total_nanos += self.weeks * 7 * 86400 * 1_000_000_000;
        total_nanos += self.months * 30 * 86400 * 1_000_000_000;
        total_nanos += self.years * 365 * 86400 * 1_000_000_000;
        total_nanos * self.n
    }

    fn __repr__(&self) -> String {
        if self.years == 0
            && self.months == 0
            && self.weeks == 0
            && self.hours == 0
            && self.minutes == 0
            && self.seconds == 0
            && self.microseconds == 0
            && self.nanoseconds == 0
            && self.days == 1
        {
            if self.n == 1 {
                return "<Day>".to_string();
            }
            return format!("<{} * Days>", self.n);
        }
        if self.years == 0
            && self.months == 0
            && self.weeks == 0
            && self.days == 0
            && self.minutes == 0
            && self.seconds == 0
            && self.microseconds == 0
            && self.nanoseconds == 0
            && self.hours == 1
        {
            if self.n == 1 {
                return "<Hour>".to_string();
            }
            return format!("<{} * Hours>", self.n);
        }
        if self.years == 0
            && self.months == 0
            && self.weeks == 0
            && self.days == 0
            && self.hours == 0
            && self.seconds == 0
            && self.microseconds == 0
            && self.nanoseconds == 0
            && self.minutes == 1
        {
            if self.n == 1 {
                return "<Minute>".to_string();
            }
            return format!("<{} * Minutes>", self.n);
        }
        if self.years == 0
            && self.months == 0
            && self.weeks == 0
            && self.days == 0
            && self.hours == 0
            && self.minutes == 0
            && self.microseconds == 0
            && self.nanoseconds == 0
            && self.seconds == 1
        {
            if self.n == 1 {
                return "<Second>".to_string();
            }
            return format!("<{} * Seconds>", self.n);
        }
        if self.years == 0
            && self.months == 0
            && self.days == 0
            && self.hours == 0
            && self.minutes == 0
            && self.seconds == 0
            && self.microseconds == 0
            && self.nanoseconds == 0
            && self.weeks == 1
        {
            if self.n == 1 {
                return "<Week>".to_string();
            }
            return format!("<{} * Weeks>", self.n);
        }
        if self.years == 0
            && self.weeks == 0
            && self.days == 0
            && self.hours == 0
            && self.minutes == 0
            && self.seconds == 0
            && self.microseconds == 0
            && self.nanoseconds == 0
            && self.months == 1
        {
            if self.n == 1 {
                return "<MonthEnd>".to_string();
            }
            return format!("<{} * MonthEnds>", self.n);
        }
        if self.months == 0
            && self.weeks == 0
            && self.days == 0
            && self.hours == 0
            && self.minutes == 0
            && self.seconds == 0
            && self.microseconds == 0
            && self.nanoseconds == 0
            && self.years == 1
        {
            if self.n == 1 {
                return "<YearEnd: month=12>".to_string();
            }
            return format!("<{} * YearEnds: month=12>", self.n);
        }

        let mut parts = Vec::new();
        if self.years != 0 {
            parts.push(format!("years={}", self.years));
        }
        if self.months != 0 {
            parts.push(format!("months={}", self.months));
        }
        if self.weeks != 0 {
            parts.push(format!("weeks={}", self.weeks));
        }
        if self.days != 0 {
            parts.push(format!("days={}", self.days));
        }
        if self.hours != 0 {
            parts.push(format!("hours={}", self.hours));
        }
        if self.minutes != 0 {
            parts.push(format!("minutes={}", self.minutes));
        }
        if self.seconds != 0 {
            parts.push(format!("seconds={}", self.seconds));
        }
        if self.microseconds != 0 {
            parts.push(format!("microseconds={}", self.microseconds));
        }
        if self.nanoseconds != 0 {
            parts.push(format!("nanoseconds={}", self.nanoseconds));
        }
        if parts.is_empty() {
            "<DateOffset>".to_string()
        } else {
            format!("<DateOffset: {}>", parts.join(", "))
        }
    }

    fn __add__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        if let Ok(ts) = other.extract::<PyRef<'_, PyTimestamp>>() {
            let res = ts.inner.add_timedelta(self.nanos());
            PyTimestamp { inner: res }.into_py_any(py)
        } else {
            Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "Can only add DateOffset to Timestamp",
            ))
        }
    }

    fn __radd__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        self.__add__(py, other)
    }
}

