#[pyclass(name = "Flags", module = "frankenpandas", skip_from_py_object)]
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PyFlags {
    #[pyo3(get, set)]
    pub allows_duplicate_labels: bool,
}

#[pymethods]
impl PyFlags {
    #[new]
    #[pyo3(signature = (obj=None, *, allows_duplicate_labels=true))]
    fn new(obj: Option<&Bound<'_, PyAny>>, allows_duplicate_labels: bool) -> Self {
        let _ = obj;
        Self {
            allows_duplicate_labels,
        }
    }

    fn __repr__(&self) -> String {
        format!(
            "<Flags(allows_duplicate_labels={})>",
            if self.allows_duplicate_labels {
                "True"
            } else {
                "False"
            }
        )
    }

    fn __eq__(&self, other: &Self) -> bool {
        self.allows_duplicate_labels == other.allows_duplicate_labels
    }

    fn __getitem__(&self, key: &str) -> PyResult<bool> {
        if key == "allows_duplicate_labels" {
            Ok(self.allows_duplicate_labels)
        } else {
            Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(
                key.to_string(),
            ))
        }
    }

    fn __setitem__(&mut self, key: &str, value: bool) -> PyResult<()> {
        if key == "allows_duplicate_labels" {
            self.allows_duplicate_labels = value;
            Ok(())
        } else {
            Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(
                key.to_string(),
            ))
        }
    }
}

#[pyfunction]
#[allow(clippy::too_many_arguments)]
#[pyo3(signature = (
    left,
    right,
    on=None,
    left_on=None,
    right_on=None,
    left_index=false,
    right_index=false,
    by=None,
    left_by=None,
    right_by=None,
    suffixes=None,
    tolerance=None,
    allow_exact_matches=true,
    direction="backward"
))]
fn merge_asof(
    left: PyRef<'_, PyDataFrame>,
    right: PyRef<'_, PyDataFrame>,
    on: Option<&str>,
    left_on: Option<&str>,
    right_on: Option<&str>,
    left_index: bool,
    right_index: bool,
    by: Option<&Bound<'_, PyAny>>,
    left_by: Option<&Bound<'_, PyAny>>,
    right_by: Option<&Bound<'_, PyAny>>,
    suffixes: Option<(&str, &str)>,
    tolerance: Option<f64>,
    allow_exact_matches: bool,
    direction: &str,
) -> PyResult<PyDataFrame> {
    // Joining on the index, and suffixes other than pandas' default, were
    // dropped (fvsao.5).
    unsupported_params(
        "merge_asof",
        &[
            ("left_index", !left_index),
            ("right_index", !right_index),
            ("suffixes", suffixes.is_none_or(|s| s == ("_x", "_y"))),
        ],
    )?;
    let on_col = on.or(left_on).or(right_on).ok_or_else(|| {
        PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "merge_asof requires an `on` or `left_on`/`right_on` column",
        )
    })?;

    let dir = match direction {
        "backward" => fp_join::AsofDirection::Backward,
        "forward" => fp_join::AsofDirection::Forward,
        "nearest" => fp_join::AsofDirection::Nearest,
        other => {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "invalid direction '{other}'; expected 'backward', 'forward', or 'nearest'"
            )));
        }
    };

    let mut opts = fp_join::MergeAsofOptions::new();
    opts.allow_exact_matches = allow_exact_matches;
    opts.tolerance = tolerance;

    let by_target = by.or(left_by).or(right_by);
    if let Some(by_val) = by_target {
        if let Ok(s) = by_val.extract::<String>() {
            opts.by = Some(vec![s]);
        } else if let Ok(list) = by_val.extract::<Vec<String>>() {
            opts.by = Some(list);
        }
    }

    let merged = fp_join::merge_asof_with_options(&left.inner, &right.inner, on_col, dir, opts)
        .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;

    let frame = DataFrame::new_with_column_order(merged.index, merged.columns, merged.column_order)
        .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;

    Ok(PyDataFrame { inner: frame })
}

#[pyfunction]
#[allow(clippy::too_many_arguments)]
#[pyo3(signature = (
    left,
    right,
    on=None,
    left_on=None,
    right_on=None,
    left_by=None,
    right_by=None,
    fill_method=None,
    suffixes=None,
    how="outer"
))]
fn merge_ordered(
    left: PyRef<'_, PyDataFrame>,
    right: PyRef<'_, PyDataFrame>,
    on: Option<&Bound<'_, PyAny>>,
    left_on: Option<&Bound<'_, PyAny>>,
    right_on: Option<&Bound<'_, PyAny>>,
    left_by: Option<&Bound<'_, PyAny>>,
    right_by: Option<&Bound<'_, PyAny>>,
    fill_method: Option<&str>,
    suffixes: Option<(&str, &str)>,
    how: Option<&str>,
) -> PyResult<PyDataFrame> {
    // This computes pandas' default outer ordered merge; the by-groups,
    // suffixes and other join types were dropped (fvsao.5).
    unsupported_params(
        "merge_ordered",
        &[
            ("left_by", left_by.is_none()),
            ("right_by", right_by.is_none()),
            ("suffixes", suffixes.is_none_or(|s| s == ("_x", "_y"))),
            ("how", how.is_none_or(|h| h == "outer")),
        ],
    )?;
    let on_target = on.or(left_on).or(right_on).ok_or_else(|| {
        PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "merge_ordered requires `on` or `left_on` / `right_on`",
        )
    })?;

    let on_cols: Vec<String> = if let Ok(s) = on_target.extract::<String>() {
        vec![s]
    } else if let Ok(list) = on_target.extract::<Vec<String>>() {
        list
    } else {
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "`on` must be a string or list of strings",
        ));
    };

    let on_refs: Vec<&str> = on_cols.iter().map(String::as_str).collect();
    let merged = fp_join::merge_ordered(&left.inner, &right.inner, &on_refs, fill_method)
        .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;

    let frame = DataFrame::new_with_column_order(merged.index, merged.columns, merged.column_order)
        .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;

    Ok(PyDataFrame { inner: frame })
}

#[pyfunction]
#[pyo3(signature = (index, warn=true))]
fn infer_freq(index: &Bound<'_, PyAny>, warn: bool) -> PyResult<Option<String>> {
    let _ = warn;
    if let Ok(dti) = index.extract::<PyRef<'_, PyDatetimeIndex>>() {
        let nanos: Vec<i64> = dti.inner.values().into_iter().flatten().collect();
        return match fp_index::infer_freq_from_nanos(&nanos) {
            Ok(f) => Ok(f),
            Err(fp_index::DateRangeError::InsufficientDates) => {
                Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "Need at least 3 dates to infer frequency",
                ))
            }
            Err(e) => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                e.to_string(),
            )),
        };
    }
    if let Ok(py_idx) = index.extract::<PyRef<'_, PyIndex>>() {
        return match fp_index::infer_freq(&py_idx.inner) {
            Ok(f) => Ok(f),
            Err(fp_index::DateRangeError::InsufficientDates) => {
                Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "Need at least 3 dates to infer frequency",
                ))
            }
            Err(e) => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                e.to_string(),
            )),
        };
    }
    if let Ok(py_s) = index.extract::<PyRef<'_, PySeries>>() {
        let mut nanos = Vec::new();
        let mut strings = Vec::new();
        let mut all_nanos = true;
        let mut all_strings = true;
        for v in py_s.inner.column().values() {
            match v {
                Scalar::Datetime64(n) => {
                    nanos.push(*n);
                    all_strings = false;
                }
                Scalar::Utf8(s) => {
                    strings.push(s.clone());
                    all_nanos = false;
                }
                _ => {
                    all_nanos = false;
                    all_strings = false;
                }
            }
        }
        if all_nanos && !nanos.is_empty() {
            return match fp_index::infer_freq_from_nanos(&nanos) {
                Ok(f) => Ok(f),
                Err(fp_index::DateRangeError::InsufficientDates) => {
                    Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "Need at least 3 dates to infer frequency",
                    ))
                }
                Err(e) => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    e.to_string(),
                )),
            };
        } else if all_strings && !strings.is_empty() {
            let refs: Vec<&str> = strings.iter().map(String::as_str).collect();
            return match fp_index::infer_freq_from_timestamps(&refs) {
                Ok(f) => Ok(f),
                Err(fp_index::DateRangeError::InsufficientDates) => {
                    Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "Need at least 3 dates to infer frequency",
                    ))
                }
                Err(e) => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    e.to_string(),
                )),
            };
        } else {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "expected datetime values",
            ));
        }
    }
    if let Ok(seq) = index.extract::<Vec<String>>() {
        let refs: Vec<&str> = seq.iter().map(String::as_str).collect();
        return match fp_index::infer_freq_from_timestamps(&refs) {
            Ok(f) => Ok(f),
            Err(fp_index::DateRangeError::InsufficientDates) => {
                Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "Need at least 3 dates to infer frequency",
                ))
            }
            Err(e) => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                e.to_string(),
            )),
        };
    }
    let py = index.py();
    if let Ok(dt_obj) = to_datetime(py, index, None, None, false) {
        let dt_bound = dt_obj.bind(py);
        if let Ok(dti) = dt_bound.extract::<PyRef<'_, PyDatetimeIndex>>() {
            let nanos: Vec<i64> = dti.inner.values().into_iter().flatten().collect();
            return match fp_index::infer_freq_from_nanos(&nanos) {
                Ok(f) => Ok(f),
                Err(fp_index::DateRangeError::InsufficientDates) => {
                    Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "Need at least 3 dates to infer frequency",
                    ))
                }
                Err(e) => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    e.to_string(),
                )),
            };
        }
    }
    Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
        "cannot infer frequency on given object",
    ))
}

#[pyfunction]
#[pyo3(signature = (data, groups, dropna=true))]
fn lreshape(
    _py: Python<'_>,
    data: &Bound<'_, PyAny>,
    groups: &Bound<'_, PyDict>,
    dropna: bool,
) -> PyResult<PyDataFrame> {
    let df: PyRef<'_, PyDataFrame> = if let Ok(d) = data.extract::<PyRef<'_, PyDataFrame>>() {
        d
    } else {
        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
            "data must be a DataFrame",
        ));
    };

    let mut group_target_names = Vec::new();
    let mut group_cols: Vec<Vec<String>> = Vec::new();
    let mut all_group_source_cols = HashSet::new();

    for (k, v) in groups.iter() {
        let target_name = k.extract::<String>()?;
        let source_cols = v.extract::<Vec<String>>()?;
        for col in &source_cols {
            all_group_source_cols.insert(col.clone());
        }
        group_target_names.push(target_name);
        group_cols.push(source_cols);
    }

    let num_slices = group_cols.first().map(|v| v.len()).unwrap_or(0);
    for cols in &group_cols {
        if cols.len() != num_slices {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "All group column lists must have equal length",
            ));
        }
    }

    let existing_cols = df.columns();
    let id_cols: Vec<String> = existing_cols
        .into_iter()
        .filter(|c| !all_group_source_cols.contains(c))
        .collect();

    let mut result_chunks: Vec<DataFrame> = Vec::new();

    for slice_idx in 0..num_slices {
        let mut slice_dict = Vec::new();
        for id_col in &id_cols {
            if let Some(col) = df.inner.column(id_col) {
                slice_dict.push((id_col.clone(), col.values().to_vec()));
            }
        }
        for (g_idx, target_name) in group_target_names.iter().enumerate() {
            let src_name = &group_cols[g_idx][slice_idx];
            if let Some(col) = df.inner.column(src_name) {
                slice_dict.push((target_name.clone(), col.values().to_vec()));
            } else {
                let nulls = vec![Scalar::Null(fp_types::NullKind::Null); df.inner.len()];
                slice_dict.push((target_name.clone(), nulls));
            }
        }

        let chunk_col_names: Vec<String> = slice_dict.iter().map(|(n, _)| n.clone()).collect();
        let chunk_col_refs: Vec<&str> = chunk_col_names.iter().map(String::as_str).collect();
        let chunk_dict: Vec<(&str, Vec<Scalar>)> = slice_dict
            .iter()
            .map(|(n, v)| (n.as_str(), v.clone()))
            .collect();
        let chunk_df = DataFrame::from_dict(&chunk_col_refs, chunk_dict)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        result_chunks.push(chunk_df);
    }

    let chunk_refs: Vec<&DataFrame> = result_chunks.iter().collect();
    let mut concatenated = if chunk_refs.is_empty() {
        empty_dataframe()
    } else {
        fp_frame::concat_dataframes(&chunk_refs)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?
    };

    if dropna && !group_target_names.is_empty() {
        let mut valid_mask = vec![false; concatenated.len()];
        for target in &group_target_names {
            if let Some(col) = concatenated.column(target) {
                for (i, val) in col.values().iter().enumerate() {
                    if !val.is_null() && !val.is_nan() {
                        valid_mask[i] = true;
                    }
                }
            }
        }
        let keep_indices: Vec<i64> = valid_mask
            .iter()
            .enumerate()
            .filter_map(|(i, &b)| if b { Some(i as i64) } else { None })
            .collect();
        concatenated = concatenated
            .take(&keep_indices, 0)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
    }

    concatenated
        .reset_index(false)
        .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;

    Ok(PyDataFrame {
        inner: concatenated,
    })
}

#[pyfunction]
#[pyo3(signature = (df, stubnames, i, j, sep="", suffix="\\d+"))]
fn wide_to_long(
    df: &Bound<'_, PyAny>,
    stubnames: &Bound<'_, PyAny>,
    i: &Bound<'_, PyAny>,
    j: &str,
    sep: &str,
    suffix: &str,
) -> PyResult<PyDataFrame> {
    let py = df.py();
    let py_df: PyRef<'_, PyDataFrame> = if let Ok(d) = df.extract::<PyRef<'_, PyDataFrame>>() {
        d
    } else {
        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
            "df must be a DataFrame",
        ));
    };

    let stubs: Vec<String> = if let Ok(s) = stubnames.extract::<String>() {
        vec![s]
    } else if let Ok(list) = stubnames.extract::<Vec<String>>() {
        list
    } else {
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "stubnames must be str or list of str",
        ));
    };

    let id_cols: Vec<String> = if let Ok(s) = i.extract::<String>() {
        vec![s]
    } else if let Ok(list) = i.extract::<Vec<String>>() {
        list
    } else {
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "i must be str or list of str",
        ));
    };

    let re_mod = py.import("re")?;
    let all_cols = py_df.columns();
    let mut suffix_values = BTreeSet::new();

    for stub in &stubs {
        let prefix = format!("{}{}", stub, sep);
        for col in &all_cols {
            if col.starts_with(&prefix) {
                let tail = &col[prefix.len()..];
                let is_match = re_mod
                    .call_method1("fullmatch", (suffix, tail))?
                    .is_truthy()?;
                if is_match {
                    suffix_values.insert(tail.to_string());
                }
            }
        }
    }

    let mut matched_cols = HashSet::new();
    for stub in &stubs {
        let prefix = format!("{}{}", stub, sep);
        for suff in &suffix_values {
            matched_cols.insert(format!("{}{}", prefix, suff));
        }
    }

    let preserved_cols: Vec<String> = all_cols
        .iter()
        .filter(|c| !id_cols.contains(c) && !matched_cols.contains(c.as_str()))
        .cloned()
        .collect();

    let n_rows = py_df.inner.len();
    let total_unpivoted_rows = n_rows * suffix_values.len();

    let mut result_columns = Vec::new();

    for id_col in &id_cols {
        let mut vals = Vec::with_capacity(total_unpivoted_rows);
        if let Some(col) = py_df.inner.column(id_col) {
            for _ in &suffix_values {
                vals.extend_from_slice(col.values());
            }
        } else {
            for _ in &suffix_values {
                for r in 0..n_rows {
                    vals.push(Scalar::Int64(r as i64));
                }
            }
        }
        result_columns.push((id_col.clone(), vals));
    }

    let mut j_vals = Vec::with_capacity(total_unpivoted_rows);
    for suff in &suffix_values {
        let s_scalar = if let Ok(int_val) = suff.parse::<i64>() {
            Scalar::Int64(int_val)
        } else {
            Scalar::Utf8(suff.clone())
        };
        for _ in 0..n_rows {
            j_vals.push(s_scalar.clone());
        }
    }
    result_columns.push((j.to_string(), j_vals));

    for col_name in &preserved_cols {
        if let Some(col) = py_df.inner.column(col_name) {
            let mut vals = Vec::with_capacity(total_unpivoted_rows);
            for _ in &suffix_values {
                vals.extend_from_slice(col.values());
            }
            result_columns.push((col_name.clone(), vals));
        }
    }

    for stub in &stubs {
        let mut vals = Vec::with_capacity(total_unpivoted_rows);
        for suff in &suffix_values {
            let col_name = format!("{}{}{}", stub, sep, suff);
            if let Some(col) = py_df.inner.column(&col_name) {
                vals.extend_from_slice(col.values());
            } else {
                vals.extend(std::iter::repeat_n(
                    Scalar::Null(fp_types::NullKind::Null),
                    n_rows,
                ));
            }
        }
        result_columns.push((stub.clone(), vals));
    }

    let col_names: Vec<String> = result_columns.iter().map(|(n, _)| n.clone()).collect();
    let col_refs: Vec<&str> = col_names.iter().map(String::as_str).collect();
    let dict_entries: Vec<(&str, Vec<Scalar>)> = result_columns
        .iter()
        .map(|(n, v)| (n.as_str(), v.clone()))
        .collect();

    let result_df = DataFrame::from_dict(&col_refs, dict_entries)
        .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;

    let mut index_col_names = id_cols.clone();
    index_col_names.push(j.to_string());
    let index_refs: Vec<&str> = index_col_names.iter().map(String::as_str).collect();

    let indexed_df = if index_refs.len() == 1 {
        result_df.set_index(index_refs[0], true)
    } else {
        result_df.set_index_multi(&index_refs, true, "/")
    }
    .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;

    Ok(PyDataFrame { inner: indexed_df })
}

#[pyclass(name = "ExcelFile", module = "frankenpandas", skip_from_py_object)]
#[derive(Clone)]
pub struct PyExcelFile {
    pub path: String,
    pub sheet_names: Vec<String>,
}

#[pymethods]
impl PyExcelFile {
    #[new]
    #[pyo3(signature = (path_or_buffer, engine=None, storage_options=None, engine_kwargs=None))]
    fn new(
        py: Python<'_>,
        path_or_buffer: &Bound<'_, PyAny>,
        engine: Option<&str>,
        storage_options: Option<&Bound<'_, PyDict>>,
        engine_kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Self> {
        // Sheet names come from fp-io's reader. This used to import openpyxl and
        // fall back to a fabricated ["Sheet1"] when anything failed.
        // engine only picks the library reading the same workbook.
        let _ = (py, engine);
        if storage_options.is_some() {
            return Err(not_implemented("ExcelFile(storage_options=...)"));
        }
        if engine_kwargs.is_some_and(|k| !k.is_empty()) {
            return Err(not_implemented("ExcelFile(engine_kwargs=...)"));
        }
        let path = py_fspath(path_or_buffer).map_err(|_| not_implemented("ExcelFile(<buffer>)"))?;
        let bytes = py_input_bytes(path_or_buffer)?;
        let sheet_names = fp_io::read_excel_sheets_ordered_bytes(
            &bytes,
            None,
            &fp_io::ExcelReadOptions::default(),
        )
        .map_err(io_error_to_py)?
        .into_iter()
        .map(|(name, _)| name)
        .collect();

        Ok(Self { path, sheet_names })
    }

    #[getter]
    fn sheet_names(&self) -> Vec<String> {
        self.sheet_names.clone()
    }

    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (sheet_name=SheetSelector::Position(0), header=Some(0), names=None, index_col=None, usecols=None, skiprows=None, **kwargs))]
    fn parse(
        &self,
        py: Python<'_>,
        sheet_name: SheetSelector,
        header: Option<usize>,
        names: Option<Vec<String>>,
        index_col: Option<&Bound<'_, PyAny>>,
        usecols: Option<Vec<String>>,
        skiprows: Option<usize>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Py<PyAny>> {
        read_excel(
            py,
            self.path.as_str().into_bound_py_any(py)?.as_ref(),
            sheet_name,
            header,
            names,
            index_col,
            usecols,
            skiprows,
            kwargs,
        )
    }

    fn close(&self) -> PyResult<()> {
        Ok(())
    }

    fn __enter__<'py>(slf: Bound<'py, Self>) -> Bound<'py, Self> {
        slf
    }

    fn __exit__(
        &self,
        _exc_type: Option<&Bound<'_, PyAny>>,
        _exc_value: Option<&Bound<'_, PyAny>>,
        _traceback: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<bool> {
        Ok(false)
    }
}

/// Not constructible yet: its `close()`/`sheets`/`book` were stubs, so
/// `with ExcelWriter(p) as w: df.to_excel(w)` produced no file.
#[pyclass(name = "ExcelWriter", module = "frankenpandas", skip_from_py_object)]
#[derive(Clone)]
pub struct PyExcelWriter;

#[pymethods]
impl PyExcelWriter {
    #[new]
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (path, engine=None, date_format=None, datetime_format=None, mode="w", storage_options=None, if_sheet_exists=None, engine_kwargs=None))]
    fn new(
        path: &Bound<'_, PyAny>,
        engine: Option<&str>,
        date_format: Option<String>,
        datetime_format: Option<String>,
        mode: &str,
        storage_options: Option<&Bound<'_, PyDict>>,
        if_sheet_exists: Option<&str>,
        engine_kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Self> {
        let _ = (
            path,
            engine,
            date_format,
            datetime_format,
            mode,
            storage_options,
            if_sheet_exists,
            engine_kwargs,
        );
        Err(not_implemented(
            "ExcelWriter (multi-sheet workbooks); use DataFrame.to_excel(path) for one sheet",
        ))
    }
}

// ── Native IO plumbing ─────────────────────────────────────────────────────
//
// br-frankenpandas-rc0923-epic-python-honest-dropin-fvsao.1. These readers and
// writers used to call REAL pandas (read_excel -> pandas -> to_csv -> fp
// read_csv, lossy) or pyarrow, and on ANY failure — including pandas being
// absent or the path not existing — returned an EMPTY DataFrame; the writers
// returned None without writing a file. Now every IO entry point either runs on
// fp-io or raises; nothing imports pandas and nothing fabricates a result.

/// Map an fp-io error onto the exception class pandas raises for the same
/// failure (callers catch FileNotFoundError / ValueError / NotImplementedError).
fn io_error_to_py(e: fp_io::IoError) -> PyErr {
    match &e {
        fp_io::IoError::Io(err) if err.kind() == std::io::ErrorKind::NotFound => {
            PyErr::new::<pyo3::exceptions::PyFileNotFoundError, _>(e.to_string())
        }
        fp_io::IoError::Io(_) => PyErr::new::<pyo3::exceptions::PyOSError, _>(e.to_string()),
        fp_io::IoError::Deferred(_) | fp_io::IoError::Orc(_) => {
            PyErr::new::<pyo3::exceptions::PyNotImplementedError, _>(e.to_string())
        }
        _ => PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()),
    }
}

fn not_implemented(what: &str) -> PyErr {
    PyErr::new::<pyo3::exceptions::PyNotImplementedError, _>(format!(
        "{what} is not supported by frankenpandas yet"
    ))
}

/// Parameters a binding accepts for pandas signature compatibility but does
/// not implement: each is paired with whether the caller left it at pandas'
/// default. The first one that was not raises NotImplementedError naming it,
/// instead of being ignored (br-frankenpandas-rc0923-epic-python-honest-dropin-fvsao.5).
fn unsupported_params(method: &str, params: &[(&str, bool)]) -> PyResult<()> {
    match params.iter().find(|(_, is_default)| !is_default) {
        Some((param, _)) => Err(not_implemented(&format!("{method}({param}=...)"))),
        None => Ok(()),
    }
}

/// pandas' EWM decay (`get_center_of_mass`): exactly one of com, span,
/// halflife and alpha, each validated with pandas' message, turned into the
/// alpha its kernels use, `1 / (1 + com)` (br-frankenpandas-n57tz: only
/// span and alpha were taken, and span went through `2 / (span + 1)`).
fn ewm_alpha(
    com: Option<f64>,
    span: Option<f64>,
    halflife: Option<f64>,
    alpha: Option<f64>,
) -> PyResult<f64> {
    let value_error =
        |message: &str| PyErr::new::<pyo3::exceptions::PyValueError, _>(message.to_owned());
    let given = [com, span, halflife, alpha]
        .iter()
        .filter(|v| v.is_some())
        .count();
    if given > 1 {
        return Err(value_error(
            "comass, span, halflife, and alpha are mutually exclusive",
        ));
    }
    let com = match (com, span, halflife, alpha) {
        (Some(com), ..) => {
            if com < 0.0 {
                return Err(value_error("comass must satisfy: comass >= 0"));
            }
            com
        }
        (_, Some(span), ..) => {
            if span < 1.0 {
                return Err(value_error("span must satisfy: span >= 1"));
            }
            (span - 1.0) / 2.0
        }
        (_, _, Some(halflife), _) => {
            if halflife <= 0.0 {
                return Err(value_error("halflife must satisfy: halflife > 0"));
            }
            let decay = 1.0 - (0.5_f64.ln() / halflife).exp();
            1.0 / decay - 1.0
        }
        (_, _, _, Some(alpha)) => {
            if alpha <= 0.0 || alpha > 1.0 {
                return Err(value_error("alpha must satisfy: 0 < alpha <= 1"));
            }
            (1.0 - alpha) / alpha
        }
        _ => {
            return Err(value_error(
                "Must pass one of comass, span, halflife, or alpha",
            ));
        }
    };
    Ok(1.0 / (1.0 + com))
}

/// A Series or DataFrame EWM with pandas' full `ewm` signature: the decay
/// becomes alpha ([`ewm_alpha`]); `adjust` and `min_periods` are honoured;
/// `ignore_na=True`, `times` and `method='table'` are refused, and `axis`
/// can only name the rows.
#[allow(clippy::too_many_arguments)]
fn exponential_window(
    method_name: &str,
    series: Option<Series>,
    dataframe: Option<DataFrame>,
    decay: (Option<f64>, Option<f64>, Option<f64>, Option<f64>),
    min_periods: usize,
    adjust: bool,
    ignore_na: bool,
    axis: Option<&Bound<'_, PyAny>>,
    times: Option<&Bound<'_, PyAny>>,
    method: &str,
) -> PyResult<PyExponentialMovingWindow> {
    let kind = if series.is_some() {
        "Series"
    } else {
        "DataFrame"
    };
    if parse_axis_param_for_type(axis, kind)?.unwrap_or(0) != 0 {
        return Err(not_implemented(&format!("{method_name}(axis=1)")));
    }
    unsupported_params(
        method_name,
        &[
            ("ignore_na", !ignore_na),
            ("times", times.is_none_or(|t| t.is_none())),
            ("method", method == "single"),
        ],
    )?;
    let (com, span, halflife, alpha) = decay;
    Ok(PyExponentialMovingWindow {
        series,
        dataframe,
        span: None,
        alpha: Some(ewm_alpha(com, span, halflife, alpha)?),
        adjust,
        min_periods,
    })
}

/// The groupby window and resample objects the binding cannot build yet.
/// pandas computes them per group and indexes the result by (key, row
/// label), and the binding returns no row MultiIndex; these methods wrapped
/// the UNGROUPED frame and so ran one window over all rows - a silently wrong
/// number (br-frankenpandas-pbpli). A refusal until the grouped result exists.
fn grouped_window_refused(what: &str) -> PyErr {
    not_implemented(&format!(
        "{what} (pandas computes it per group under a (key, row) MultiIndex)"
    ))
}

/// A keyword argument that was passed and is not None.
fn passed<'py>(obj: Option<&Bound<'py, PyAny>>) -> Option<Bound<'py, PyAny>> {
    obj.filter(|o| !o.is_none()).cloned()
}

/// A pandas label-or-labels argument (`drop(labels=...)`, `index=`,
/// `columns=`): a list, tuple, set or Index gives its labels; anything else,
/// a string included, is one label.
fn py_label_list(obj: &Bound<'_, PyAny>) -> PyResult<Vec<IndexLabel>> {
    if let Ok(index) = obj.extract::<PyRef<'_, PyIndex>>() {
        return Ok(index.inner.labels().to_vec());
    }
    if obj.is_instance_of::<PyList>()
        || obj.is_instance_of::<PyTuple>()
        || obj.is_instance_of::<pyo3::types::PySet>()
    {
        return obj
            .try_iter()?
            .map(|item| py_to_index_label(&item?))
            .collect();
    }
    Ok(vec![py_to_index_label(obj)?])
}

/// One axis of pandas' `rename`: a dict renames the keys found among
/// `labels` (with `raise`, a key the axis lacks is pandas' KeyError), and a
/// callable renames every label (br-frankenpandas-n57tz).
fn rename_pairs(
    py: Python<'_>,
    mapping: &Bound<'_, PyAny>,
    labels: &[IndexLabel],
    raise: bool,
) -> PyResult<Vec<(IndexLabel, IndexLabel)>> {
    if let Ok(dict) = mapping.cast::<PyDict>() {
        let present: HashSet<&IndexLabel> = labels.iter().collect();
        let mut pairs = Vec::with_capacity(dict.len());
        let mut missing = Vec::new();
        for (key, value) in dict.iter() {
            let key = py_to_index_label(&key)?;
            if present.contains(&key) {
                pairs.push((key, py_to_index_label(&value)?));
            } else {
                missing.push(key);
            }
        }
        if raise && !missing.is_empty() {
            return Err(not_found_in_axis(py, &missing)?);
        }
        return Ok(pairs);
    }
    if mapping.is_callable() {
        return labels
            .iter()
            .map(|label| {
                let renamed = mapping.call1((index_label_to_py(py, label)?,))?;
                Ok((label.clone(), py_to_index_label(&renamed)?))
            })
            .collect();
    }
    Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
        "'{}' object is not callable",
        mapping.get_type().name()?
    )))
}

/// pandas' KeyError for labels an axis does not hold:
/// `"['q', 'r'] not found in axis"`.
fn not_found_in_axis(py: Python<'_>, missing: &[IndexLabel]) -> PyResult<PyErr> {
    let items = missing
        .iter()
        .map(|label| index_label_to_py(py, label))
        .collect::<PyResult<Vec<_>>>()?;
    let listed = PyList::new(py, items)?.repr()?.to_string();
    Ok(PyErr::new::<pyo3::exceptions::PyKeyError, _>(format!(
        "{listed} not found in axis"
    )))
}

/// pandas' groupby `engine=`: "numba" JIT-compiles the reduction, which
/// frankenpandas cannot; every other value runs pandas' default kernels, and
/// `engine_kwargs` only ever reaches numba (br-frankenpandas-n57tz).
fn groupby_engine(method: &str, engine: Option<&str>) -> PyResult<()> {
    if engine == Some("numba") {
        return Err(not_implemented(&format!("{method}(engine='numba')")));
    }
    Ok(())
}

/// A groupby `ddof`; pandas also takes a negative one, which is refused.
fn groupby_ddof(method: &str, ddof: i64) -> PyResult<usize> {
    usize::try_from(ddof).map_err(|_| not_implemented(&format!("{method}(ddof={ddof})")))
}

/// Labels 0..n, so a sorted copy records where each row came from (the
/// key= sorts, fvsao.5).
fn position_labels(n: usize) -> Vec<IndexLabel> {
    (0..n)
        .map(|i| IndexLabel::Int64(i64::try_from(i).unwrap_or(i64::MAX)))
        .collect()
}

/// The row order a sort of a `position_labels` copy produced.
fn positions_from_labels(labels: &[IndexLabel]) -> PyResult<Vec<i64>> {
    labels
        .iter()
        .map(|label| match label {
            IndexLabel::Int64(i) => Ok(*i),
            other => Err(PyErr::new::<pyo3::exceptions::PyRuntimeError, _>(format!(
                "keyed sort lost its position label: {other:?}"
            ))),
        })
        .collect()
}

/// pandas' `sort_values` on nanosecond labels: NaT (the `i64::MIN`
/// sentinel) goes to `na_position` and the rest sort by value (fvsao.5:
/// na_position was dropped and NaT, the smallest i64, always sorted first).
fn sort_nanos_na(values: &[i64], ascending: bool, na_position: &str) -> PyResult<Vec<i64>> {
    let (mut valid, nat): (Vec<i64>, Vec<i64>) = values.iter().partition(|&&v| v != i64::MIN);
    if ascending {
        valid.sort_unstable();
    } else {
        valid.sort_unstable_by(|a, b| b.cmp(a));
    }
    match na_position {
        "last" => {
            valid.extend(nat);
            Ok(valid)
        }
        "first" => Ok(nat.into_iter().chain(valid).collect()),
        other => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
            "invalid na_position: {other}"
        ))),
    }
}

/// pandas' `Index.sort_values(ascending, na_position)` over labels: missing
/// labels go to `na_position` and the rest sort ascending or descending
/// (fvsao.5: na_position was dropped, and reversing an ascending sort put the
/// missing labels first for a descending one).
fn sort_labels_na(index: &Index, ascending: bool, na_position: &str) -> PyResult<Index> {
    let (valid, missing): (Vec<IndexLabel>, Vec<IndexLabel>) = index
        .labels()
        .iter()
        .cloned()
        .partition(|l| !l.is_missing());
    let mut sorted = Index::new(valid).sort_values().labels().to_vec();
    if !ascending {
        sorted.reverse();
    }
    let labels = match na_position {
        "last" => sorted.into_iter().chain(missing).collect(),
        "first" => missing.into_iter().chain(sorted).collect(),
        other => {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "invalid na_position: {other}"
            )));
        }
    };
    Ok(Index::new(labels).rename_index(index.name()))
}

/// A flat index has one level; pandas' `droplevel` refuses to remove it.
fn flat_droplevel_error() -> PyErr {
    PyErr::new::<pyo3::exceptions::PyValueError, _>(
        "Cannot remove 1 levels from an index with 1 levels: at least one level must be left.",
    )
}

/// A flat index has only level 0.
fn flat_level_check(level: usize) -> PyResult<()> {
    if level == 0 {
        Ok(())
    } else {
        Err(PyErr::new::<pyo3::exceptions::PyIndexError, _>(format!(
            "Too many levels: Index has only 1 level, not {}",
            level + 1
        )))
    }
}

/// `kind=` only picks numpy's sort algorithm. frankenpandas' sort is stable,
/// which is exactly `stable`/`mergesort` and a valid order for the unstable
/// kinds, so a known kind is honoured and an unknown one raises as numpy does
/// (fvsao.5).
fn validate_sort_kind(kind: Option<&str>) -> PyResult<()> {
    match kind {
        None
        | Some("quicksort" | "quick" | "mergesort" | "merge" | "heapsort" | "heap" | "stable") => {
            Ok(())
        }
        Some(other) => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
            "sort kind must be one of 'quick', 'heap', or 'stable' (got '{other}')"
        ))),
    }
}

/// frankenpandas' plots draw a default SVG; pandas hands these arguments to
/// matplotlib, so any of them raises instead of being dropped (fvsao.5).
fn plot_args(args: &Bound<'_, PyTuple>, kwargs: Option<&Bound<'_, PyDict>>) -> PyResult<()> {
    if !args.is_empty() {
        return Err(not_implemented(
            "plotting arguments (frankenpandas draws a default SVG, not matplotlib)",
        ));
    }
    plot_kwargs(kwargs)
}

/// The keyword half of [`plot_args`].
fn plot_kwargs(kwargs: Option<&Bound<'_, PyDict>>) -> PyResult<()> {
    if kwargs.is_some_and(|k| !k.is_empty()) {
        return Err(not_implemented(
            "plotting arguments (frankenpandas draws a default SVG, not matplotlib)",
        ));
    }
    Ok(())
}

/// pandas' window `apply(func, args=, kwargs=)` calls
/// `func(window, *args, **kwargs)`; both used to be dropped (fvsao.5).
fn call_window_func<'py>(
    func: &Bound<'py, PyAny>,
    window: Bound<'py, PyAny>,
    args: Option<&Bound<'py, PyTuple>>,
    kwargs: Option<&Bound<'py, PyDict>>,
) -> PyResult<Bound<'py, PyAny>> {
    func.call(prepend_arg(window, args)?, kwargs)
}

/// `(first, *rest)`, for pandas' `func(x, *args, **kwargs)` calls.
fn prepend_arg<'py>(
    first: Bound<'py, PyAny>,
    rest: Option<&Bound<'py, PyTuple>>,
) -> PyResult<Bound<'py, PyTuple>> {
    let py = first.py();
    let mut items = vec![first];
    items.extend(rest.into_iter().flat_map(|r| r.iter()));
    PyTuple::new(py, items)
}

/// pandas' rule for the `**kwargs` of reductions, `take` and `transpose`: they
/// exist for numpy compatibility, so a numpy keyword left at its default
/// (`None`, or `False` for keepdims) passes, any other value raises ValueError,
/// and a keyword numpy does not have raises TypeError (fvsao.5).
fn numpy_compat_kwargs(method: &str, kwargs: Option<&Bound<'_, PyDict>>) -> PyResult<()> {
    const NUMPY_KEYWORDS: [&str; 7] = [
        "out", "dtype", "keepdims", "axes", "initial", "where", "mode",
    ];
    let Some(kwargs) = kwargs else {
        return Ok(());
    };
    for (key, value) in kwargs.iter() {
        let key: String = key.extract()?;
        if !NUMPY_KEYWORDS.contains(&key.as_str()) {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                "{method}() got an unexpected keyword argument '{key}'"
            )));
        }
        let at_default =
            value.is_none() || (key == "keepdims" && matches!(value.extract::<bool>(), Ok(false)));
        if !at_default {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "the '{key}' parameter is not supported in the pandas implementation of {method}()"
            )));
        }
    }
    Ok(())
}

/// pandas hands these `**kwargs` to an engine frankenpandas does not use
/// (tabulate, scipy, pyarrow, the clipboard): any keyword raises
/// NotImplementedError instead of being dropped (fvsao.5).
fn engine_kwargs(method: &str, engine: &str, kwargs: Option<&Bound<'_, PyDict>>) -> PyResult<()> {
    match kwargs.and_then(|kw| kw.keys().iter().next()) {
        Some(key) => Err(not_implemented(&format!(
            "{method}({key}=...), a keyword pandas passes to {engine},"
        ))),
        None => Ok(()),
    }
}

/// `os.fspath(obj)` for str and os.PathLike inputs.
fn py_fspath(obj: &Bound<'_, PyAny>) -> PyResult<String> {
    if let Ok(s) = obj.extract::<String>() {
        return Ok(s);
    }
    obj.py()
        .import("os")?
        .call_method1("fspath", (obj,))?
        .extract::<String>()
}

/// Input bytes from a pandas-style source: raw bytes, a file-like object with
/// `read()`, or a path (str / os.PathLike). A missing path raises
/// FileNotFoundError, as pandas does.
fn py_input_bytes(obj: &Bound<'_, PyAny>) -> PyResult<Vec<u8>> {
    if let Ok(b) = obj.cast::<pyo3::types::PyBytes>() {
        return Ok(b.as_bytes().to_vec());
    }
    if !obj.is_instance_of::<pyo3::types::PyString>()
        && let Ok(read) = obj.getattr("read")
    {
        let data = read.call0()?;
        if let Ok(b) = data.cast::<pyo3::types::PyBytes>() {
            return Ok(b.as_bytes().to_vec());
        }
        return Ok(data.extract::<String>()?.into_bytes());
    }
    let path = py_fspath(obj)?;
    std::fs::read(&path).map_err(|e| {
        io_error_to_py(fp_io::IoError::Io(std::io::Error::new(
            e.kind(),
            format!("{e}: '{path}'"),
        )))
    })
}

/// Input text from a path, a file-like object, or raw bytes (UTF-8). Invalid
/// UTF-8 is a ValueError (UnicodeDecodeError's base; its own constructor needs
/// the raw object and offsets).
fn py_input_text(obj: &Bound<'_, PyAny>) -> PyResult<String> {
    String::from_utf8(py_input_bytes(obj)?).map_err(|e| {
        PyErr::new::<pyo3::exceptions::PyValueError, _>(format!("input is not valid UTF-8: {e}"))
    })
}

/// Write bytes to a pandas-style target (path or binary file-like). With no
/// target the bytes are returned, as `DataFrame.to_parquet(None)` does.
fn py_output_bytes(
    py: Python<'_>,
    target: Option<&Bound<'_, PyAny>>,
    bytes: Vec<u8>,
) -> PyResult<Option<Py<PyAny>>> {
    let Some(target) = target.filter(|t| !t.is_none()) else {
        return Ok(Some(
            pyo3::types::PyBytes::new(py, &bytes).into_any().unbind(),
        ));
    };
    if !target.is_instance_of::<pyo3::types::PyString>()
        && let Ok(write) = target.getattr("write")
    {
        write.call1((pyo3::types::PyBytes::new(py, &bytes),))?;
        return Ok(None);
    }
    let path = py_fspath(target)?;
    std::fs::write(&path, bytes).map_err(|e| io_error_to_py(fp_io::IoError::Io(e)))?;
    Ok(None)
}

/// Text counterpart of `py_output_bytes`: a path, a text file-like, or (no
/// target) the string itself, as `DataFrame.to_latex(None)` does.
fn py_output_text(target: Option<&Bound<'_, PyAny>>, text: String) -> PyResult<Option<String>> {
    let Some(target) = target.filter(|t| !t.is_none()) else {
        return Ok(Some(text));
    };
    if !target.is_instance_of::<pyo3::types::PyString>()
        && let Ok(write) = target.getattr("write")
    {
        write.call1((text,))?;
        return Ok(None);
    }
    let path = py_fspath(target)?;
    std::fs::write(&path, text).map_err(|e| io_error_to_py(fp_io::IoError::Io(e)))?;
    Ok(None)
}

/// True for an unnamed 0..n Int64 row index — the one index fp-io's Arrow
/// writers can omit without losing information (pandas stores it as metadata).
fn has_default_range_index(frame: &DataFrame) -> bool {
    let index = frame.index();
    frame.row_multiindex().is_none()
        && index.name().is_none()
        && index.labels().iter().enumerate().all(|(pos, label)| {
            matches!(label, IndexLabel::Int64(v) if usize::try_from(*v).ok() == Some(pos))
        })
}

/// `Series.to_frame()` for the Series writers: an unnamed Series becomes column
/// `0`, as in pandas.
/// pandas' `to_csv` keywords, shared by `DataFrame.to_csv` and
/// `Series.to_csv` (fvsao.5: Series dropped every keyword but sep/index, and
/// DataFrame took only path/index).
struct CsvWriteArgs<'a, 'py> {
    sep: &'a str,
    na_rep: &'a str,
    float_format: Option<&'a Bound<'py, PyAny>>,
    columns: Option<&'a Bound<'py, PyAny>>,
    /// `None` is pandas' default, `True`.
    header: Option<&'a Bound<'py, PyAny>>,
    index: bool,
    index_label: Option<&'a Bound<'py, PyAny>>,
    mode: &'a str,
    encoding: Option<&'a str>,
    /// pandas' default is `Some("infer")`; an explicit `None` never compresses.
    compression: Option<&'a str>,
    quoting: Option<i64>,
    quotechar: &'a str,
    lineterminator: Option<&'a str>,
    date_format: Option<&'a str>,
    doublequote: bool,
    escapechar: Option<&'a str>,
    decimal: &'a str,
    storage_options: Option<&'a Bound<'py, PyAny>>,
}

/// Write `frame` as pandas' `to_csv` does. sep, na_rep, columns, header,
/// index, index_label and mode ('w'/'a') are honoured; chunksize and errors
/// cannot change UTF-8 output; every other keyword raises NotImplementedError
/// at a non-default value. `path_or_buf` may be None (return the text), a
/// path, or a file-like object with `write`.
fn write_csv_py(
    method: &str,
    frame: &DataFrame,
    path_or_buf: Option<&Bound<'_, PyAny>>,
    args: &CsvWriteArgs<'_, '_>,
) -> PyResult<Option<String>> {
    let compression_is_default = compression_is_plain(args.compression, path_or_buf)?;
    unsupported_params(
        method,
        &[
            ("float_format", args.float_format.is_none()),
            (
                "header",
                args.header.is_none_or(|h| h.extract::<bool>().is_ok()),
            ),
            (
                "index_label",
                args.index_label
                    .is_none_or(|l| l.is_none() || l.extract::<String>().is_ok()),
            ),
            ("mode", matches!(args.mode, "w" | "a")),
            (
                "encoding",
                args.encoding
                    .is_none_or(|e| matches!(e.to_ascii_lowercase().as_str(), "utf-8" | "utf8")),
            ),
            ("compression", compression_is_default),
            ("quoting", matches!(args.quoting, None | Some(0))),
            ("quotechar", args.quotechar == "\""),
            (
                "lineterminator",
                matches!(args.lineterminator, None | Some("\n")),
            ),
            ("date_format", args.date_format.is_none()),
            ("doublequote", args.doublequote),
            ("escapechar", args.escapechar.is_none()),
            ("decimal", args.decimal == "."),
            ("storage_options", args.storage_options.is_none()),
        ],
    )?;
    let delimiter = match args.sep.as_bytes() {
        [b] if b.is_ascii() => *b,
        _ => {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "\"delimiter\" must be a 1-character string",
            ));
        }
    };
    let selected;
    let frame = match args.columns {
        Some(cols) if !cols.is_none() => {
            let names = extract_col_names_flexible(Some(cols))?;
            let refs: Vec<&str> = names.iter().map(String::as_str).collect();
            selected = frame.select_columns(&refs).map_err(frame_error_to_py)?;
            &selected
        }
        _ => frame,
    };
    let options = fp_io::CsvWriteOptions {
        delimiter,
        na_rep: args.na_rep.to_owned(),
        header: args.header.map_or(Ok(true), |h| h.extract::<bool>())?,
        include_index: args.index,
        index_label: args.index_label.and_then(|l| l.extract::<String>().ok()),
    };
    let text = fp_io::write_csv_string_with_options(frame, &options).map_err(io_error_to_py)?;
    write_text_target(path_or_buf, text, args.mode == "a")
}

/// Where pandas' text writers send their output: no target returns the text,
/// a path (str / os.PathLike) is written (appended when `append`), and an
/// object with `write` receives the text.
fn write_text_target(
    target: Option<&Bound<'_, PyAny>>,
    text: String,
    append: bool,
) -> PyResult<Option<String>> {
    let Some(target) = target.filter(|t| !t.is_none()) else {
        return Ok(Some(text));
    };
    if target.hasattr("write")? {
        target.call_method1("write", (text,))?;
        return Ok(None);
    }
    let path = py_fspath(target)?;
    let mut file = std::fs::OpenOptions::new()
        .write(true)
        .create(true)
        .append(append)
        .truncate(!append)
        .open(&path)
        .map_err(|e| PyErr::new::<pyo3::exceptions::PyIOError, _>(e.to_string()))?;
    std::io::Write::write_all(&mut file, text.as_bytes())
        .map_err(|e| PyErr::new::<pyo3::exceptions::PyIOError, _>(e.to_string()))?;
    Ok(None)
}

/// pandas' `to_json` keywords around `orient`, shared by DataFrame and
/// Series (fvsao.5: they were dropped through `**kwargs`).
struct JsonWriteArgs<'a, 'py> {
    date_format: Option<&'a str>,
    double_precision: i64,
    force_ascii: bool,
    date_unit: &'a str,
    default_handler: Option<&'a Bound<'py, PyAny>>,
    lines: bool,
    compression: Option<&'a str>,
    index: Option<bool>,
    indent: Option<i64>,
    storage_options: Option<&'a Bound<'py, PyAny>>,
    mode: &'a str,
}

/// Write pandas' `to_json` output. `render(lines)` produces the JSON text
/// (JSON Lines when `lines`). force_ascii escapes non-ASCII as pandas does
/// (the default, which frankenpandas used to skip), lines and mode='a' follow
/// pandas' rules, and every other keyword raises NotImplementedError at a
/// non-default value.
fn write_json_py(
    method: &str,
    path_or_buf: Option<&Bound<'_, PyAny>>,
    orient: Option<&str>,
    args: &JsonWriteArgs<'_, '_>,
    render: impl FnOnce(bool) -> PyResult<String>,
) -> PyResult<Option<String>> {
    unsupported_params(
        method,
        &[
            ("date_format", args.date_format.is_none()),
            ("double_precision", args.double_precision == 10),
            ("date_unit", args.date_unit == "ms"),
            ("default_handler", args.default_handler.is_none()),
            (
                "compression",
                compression_is_plain(args.compression, path_or_buf)?,
            ),
            ("index", args.index.is_none()),
            ("indent", args.indent.is_none()),
            ("storage_options", args.storage_options.is_none()),
        ],
    )?;
    if args.lines && orient != Some("records") {
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "'lines' keyword only valid when 'orient' is records",
        ));
    }
    match args.mode {
        "w" => {}
        "a" if args.lines => {}
        "a" => {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "mode='a' (append) is only supported when lines is True and orient is 'records'",
            ));
        }
        other => {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "mode={other} is not a valid option.Only 'w' and 'a' are currently supported."
            )));
        }
    }
    let text = render(args.lines)?;
    let text = if args.force_ascii {
        ascii_escape_json(&text)
    } else {
        text
    };
    write_text_target(path_or_buf, text, args.mode == "a")
}

/// pandas' `force_ascii=True`: every non-ASCII character becomes a `\uXXXX`
/// escape (a surrogate pair above U+FFFF). Non-ASCII only occurs inside JSON
/// strings, so escaping the whole text is exact.
fn ascii_escape_json(text: &str) -> String {
    if text.is_ascii() {
        return text.to_owned();
    }
    let mut out = String::with_capacity(text.len() + 16);
    for c in text.chars() {
        if c.is_ascii() {
            out.push(c);
        } else {
            let mut units = [0_u16; 2];
            for unit in c.encode_utf16(&mut units) {
                out.push_str(&format!("\\u{unit:04x}"));
            }
        }
    }
    out
}

/// pandas' `compression='infer'` compresses a path ending in a compression
/// extension. frankenpandas writes plain text, so that case (and any explicit
/// compression) is refused rather than written uncompressed (fvsao.5).
fn compression_is_plain(
    compression: Option<&str>,
    target: Option<&Bound<'_, PyAny>>,
) -> PyResult<bool> {
    const COMPRESSED: [&str; 7] = [".gz", ".bz2", ".zip", ".xz", ".zst", ".tar", ".tgz"];
    let path = match target {
        Some(t) if !t.is_none() && !t.hasattr("write")? => Some(py_fspath(t)?),
        _ => None,
    };
    let infers = path
        .as_deref()
        .is_some_and(|p| COMPRESSED.iter().any(|ext| p.ends_with(ext)));
    Ok(match compression {
        None => true,
        Some("infer") => !infers,
        Some(_) => false,
    })
}

fn series_as_frame(series: &Series) -> PyResult<PyDataFrame> {
    let name = if series.name().is_empty() {
        "0"
    } else {
        series.name()
    };
    Ok(PyDataFrame {
        inner: series.to_frame(Some(name)).map_err(frame_error_to_py)?,
    })
}

/// fp-io's Parquet/Feather writers serialize columns only; refuse rather than
/// silently drop a label index pandas would have kept.
fn arrow_writer_frame(func: &str, frame: &DataFrame, index: Option<bool>) -> PyResult<()> {
    if index != Some(false) && !has_default_range_index(frame) {
        return Err(not_implemented(&format!(
            "{func} with a non-default index (call reset_index() first, or pass index=False)"
        )));
    }
    Ok(())
}

/// Keyword arguments this binding does not implement: any non-None value raises
/// NotImplementedError naming it, instead of being silently ignored.
fn reject_unsupported_kwargs(
    func: &str,
    kwargs: Option<&Bound<'_, PyDict>>,
    ignorable: &[&str],
) -> PyResult<()> {
    if let Some(kwargs) = kwargs {
        for (key, value) in kwargs.iter() {
            let key = key.extract::<String>()?;
            if !value.is_none() && !ignorable.contains(&key.as_str()) {
                return Err(not_implemented(&format!("{func}({key}=...)")));
            }
        }
    }
    Ok(())
}

fn select_columns_arg(frame: DataFrame, columns: Option<&Bound<'_, PyAny>>) -> PyResult<DataFrame> {
    match columns.filter(|c| !c.is_none()) {
        None => Ok(frame),
        Some(cols) => {
            let names = cols.extract::<Vec<String>>()?;
            frame
                .select_columns(&names.iter().map(String::as_str).collect::<Vec<_>>())
                .map_err(loc_key_error)
        }
    }
}

/// pandas' `sheet_name`: a position, a name, or None for every sheet. A
/// dedicated type so an explicit `None` is distinguishable from the default 0.
enum SheetSelector {
    All,
    Position(usize),
    Name(String),
}

impl<'a, 'py> FromPyObject<'a, 'py> for SheetSelector {
    type Error = PyErr;

    fn extract(obj: pyo3::Borrowed<'a, 'py, PyAny>) -> PyResult<Self> {
        if obj.is_none() {
            return Ok(Self::All);
        }
        if let Ok(pos) = obj.extract::<usize>() {
            return Ok(Self::Position(pos));
        }
        Ok(Self::Name(obj.extract::<String>()?))
    }
}

/// `pd.read_excel` on fp-io's calamine reader. sheet_name: str, int (position)
/// or None (dict of every sheet). `engine` is accepted and ignored (there is one
/// engine); other unsupported options raise NotImplementedError.
#[pyfunction]
#[allow(clippy::too_many_arguments)]
#[pyo3(signature = (io, sheet_name=SheetSelector::Position(0), header=Some(0), names=None, index_col=None, usecols=None, skiprows=None, **kwargs))]
fn read_excel(
    py: Python<'_>,
    io: &Bound<'_, PyAny>,
    sheet_name: SheetSelector,
    header: Option<usize>,
    names: Option<Vec<String>>,
    index_col: Option<&Bound<'_, PyAny>>,
    usecols: Option<Vec<String>>,
    skiprows: Option<usize>,
    kwargs: Option<&Bound<'_, PyDict>>,
) -> PyResult<Py<PyAny>> {
    reject_unsupported_kwargs("read_excel", kwargs, &["engine"])?;
    let bytes = py_input_bytes(io)?;
    let options = fp_io::ExcelReadOptions {
        sheet_name: None,
        has_headers: header.is_some(),
        usecols,
        names,
        index_col: None,
        skip_rows: skiprows.unwrap_or(0) + header.unwrap_or(0),
    };
    let finish = |frame: DataFrame| -> PyResult<DataFrame> {
        match index_col.filter(|c| !c.is_none()) {
            None => Ok(frame),
            Some(col) => {
                let name = if let Ok(pos) = col.extract::<usize>() {
                    frame
                        .column_names()
                        .get(pos)
                        .map(|s| s.to_string())
                        .ok_or_else(|| loc_key_error(format!("index_col {pos}")))?
                } else {
                    col.extract::<String>()?
                };
                frame.set_index(&name, true).map_err(frame_error_to_py)
            }
        }
    };
    let sheets =
        fp_io::read_excel_sheets_ordered_bytes(&bytes, None, &options).map_err(io_error_to_py)?;
    let (found, wanted) = match sheet_name {
        SheetSelector::All => {
            let out = PyDict::new(py);
            for (name, frame) in sheets {
                out.set_item(
                    name,
                    Py::new(
                        py,
                        PyDataFrame {
                            inner: finish(frame)?,
                        },
                    )?,
                )?;
            }
            return Ok(out.into_any().unbind());
        }
        SheetSelector::Position(pos) => (
            sheets.into_iter().nth(pos).map(|(_, f)| f),
            format!("index {pos}"),
        ),
        SheetSelector::Name(want) => {
            let found = sheets.into_iter().find(|(n, _)| *n == want).map(|(_, f)| f);
            (found, format!("named '{want}'"))
        }
    };
    let frame = found.ok_or_else(|| {
        PyErr::new::<pyo3::exceptions::PyValueError, _>(format!("Worksheet {wanted} not found"))
    })?;
    Ok(Py::new(
        py,
        PyDataFrame {
            inner: finish(frame)?,
        },
    )?
    .into_any())
}

