    #[test]
    fn test_py_windowing_and_series_math() {
        let s = Series::from_values(
            "val",
            vec![
                IndexLabel::Int64(0),
                IndexLabel::Int64(1),
                IndexLabel::Int64(2),
                IndexLabel::Int64(3),
            ],
            vec![
                Scalar::Float64(1.0),
                Scalar::Float64(2.0),
                Scalar::Float64(3.0),
                Scalar::Float64(4.0),
            ],
        )
        .expect("series"); // ubs:ignore — test fixture
        let py_s = PySeries { inner: s };

        let roll = py_s.rolling(2, None, false);
        assert_eq!(roll.window, 2);
        assert!(!roll.center);

        let exp = py_s.expanding(None);
        assert_eq!(exp.min_periods, None);

        // span=3 is pandas' com=1, alpha=0.5 (br-frankenpandas-n57tz); span=0.5
        // is pandas' ValueError (span >= 1), which this used to accept.
        let ewm = py_s
            .ewm(
                None,
                Some(3.0),
                None,
                None,
                0,
                true,
                false,
                None,
                None,
                "single",
            )
            .expect("ewm span=3"); // ubs:ignore — test fixture
        assert_eq!(ewm.alpha, Some(0.5));
        assert!(
            py_s.ewm(
                None,
                Some(0.5),
                None,
                None,
                0,
                true,
                false,
                None,
                None,
                "single"
            )
            .is_err()
        );

        let s2 = py_s.clone();
        let c = py_s.corr(&s2, None, None).expect("corr"); // ubs:ignore — test fixture
        assert!((c - 1.0).abs() < 1e-6);

        let ffilled = py_s.ffill(None, false, None, None, None).expect("ffill"); // ubs:ignore — test fixture
        assert_eq!(ffilled.inner.len(), 4);
    }

